#!/usr/bin/env python3
"""
Validate a task plan structure for completeness and correctness.

Usage:
    python validate-plan.py <plan.json>
    python validate-plan.py --stdin < plan.json
"""

import json
import sys
from typing import Any


def validate_step(step: dict, step_index: int, all_step_ids: set) -> list[str]:
    """Validate a single plan step."""
    errors = []
    prefix = f"Step {step_index + 1}"

    # Required fields
    required = ['id', 'title', 'action', 'successCriteria']
    for field in required:
        if field not in step:
            errors.append(f"{prefix}: Missing required field '{field}'")

    # ID uniqueness
    if 'id' in step:
        if step['id'] in all_step_ids:
            errors.append(f"{prefix}: Duplicate step ID '{step['id']}'")
        all_step_ids.add(step['id'])

    # Dependencies reference valid steps
    deps = step.get('dependencies', [])
    for dep in deps:
        if dep not in all_step_ids and dep != step.get('id'):
            # Allow forward references, but warn
            pass  # Will be checked in second pass

    # Complexity is valid
    complexity = step.get('complexity')
    if complexity and complexity not in ['low', 'medium', 'high']:
        errors.append(f"{prefix}: Invalid complexity '{complexity}' (must be low/medium/high)")

    # Status is valid
    status = step.get('status')
    if status and status not in ['pending', 'in_progress', 'complete', 'failed', 'skipped']:
        errors.append(f"{prefix}: Invalid status '{status}'")

    return errors


def validate_plan(plan: dict) -> list[str]:
    """Validate a complete task plan."""
    errors = []

    # Required top-level fields
    if 'steps' not in plan:
        errors.append("Plan missing 'steps' array")
        return errors

    steps = plan['steps']
    if not isinstance(steps, list):
        errors.append("'steps' must be an array")
        return errors

    if len(steps) == 0:
        errors.append("Plan has no steps")
        return errors

    if len(steps) > 10:
        errors.append(f"Plan has too many steps ({len(steps)}). Consider breaking into sub-plans.")

    # Collect all step IDs first
    all_step_ids = set()
    for step in steps:
        if 'id' in step:
            all_step_ids.add(step['id'])

    # Validate each step
    for i, step in enumerate(steps):
        errors.extend(validate_step(step, i, set(all_step_ids)))

    # Check for dependency cycles
    def has_cycle(step_id: str, visited: set, path: set) -> bool:
        if step_id in path:
            return True
        if step_id in visited:
            return False

        visited.add(step_id)
        path.add(step_id)

        step = next((s for s in steps if s.get('id') == step_id), None)
        if step:
            for dep in step.get('dependencies', []):
                if has_cycle(dep, visited, path):
                    return True

        path.remove(step_id)
        return False

    visited = set()
    for step in steps:
        if 'id' in step and has_cycle(step['id'], visited, set()):
            errors.append(f"Circular dependency detected involving step '{step['id']}'")
            break

    # Check for orphaned dependencies
    for step in steps:
        for dep in step.get('dependencies', []):
            if dep not in all_step_ids:
                errors.append(f"Step '{step.get('id')}' depends on non-existent step '{dep}'")

    return errors


def main():
    if len(sys.argv) < 2 or sys.argv[1] == '--stdin':
        data = sys.stdin.read()
    else:
        with open(sys.argv[1]) as f:
            data = f.read()

    try:
        plan = json.loads(data)
    except json.JSONDecodeError as e:
        print(f"Invalid JSON: {e}", file=sys.stderr)
        sys.exit(1)

    errors = validate_plan(plan)

    if errors:
        print("Plan validation failed:")
        for error in errors:
            print(f"  - {error}")
        sys.exit(1)
    else:
        print("Plan is valid ✓")
        print(f"  Steps: {len(plan.get('steps', []))}")

        # Show summary
        statuses = {}
        for step in plan.get('steps', []):
            status = step.get('status', 'pending')
            statuses[status] = statuses.get(status, 0) + 1

        if statuses:
            print("  Status breakdown:")
            for status, count in sorted(statuses.items()):
                print(f"    {status}: {count}")


if __name__ == '__main__':
    main()

/**
 * Agent path utilities
 */

import path from "node:path";
import os from "node:os";

/**
 * Resolve the OpenClaw agent directory (~/.openclaw)
 */
export function resolveOpenClawAgentDir(): string {
  return process.env.OPENCLAW_AGENT_DIR || process.env.CLAWDBOT_DIR || path.join(os.homedir(), ".openclaw");
}

/** @deprecated Use resolveOpenClawAgentDir */
export const resolveClawdbotAgentDir = resolveOpenClawAgentDir;

/**
 * Proactive Context Management
 * 
 * Manage context window efficiently with summarization and pruning.
 */

import type {
  TokenBudget,
  WorkingMemory,
  WorkingMemoryEntry,
  ContextConfig,
  AgentMessage,
  LLMCaller,
} from "../types.js";

// ============================================================================
// Token Estimation
// ============================================================================

/**
 * Rough token estimation (4 chars per token average)
 */
export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

/**
 * Estimate tokens for messages
 */
export function estimateMessageTokens(messages: AgentMessage[]): number {
  let total = 0;
  for (const msg of messages) {
    if (typeof msg.content === "string") {
      total += estimateTokens(msg.content);
    } else if (Array.isArray(msg.content)) {
      for (const block of msg.content) {
        if (block.text) {
          total += estimateTokens(block.text);
        }
      }
    }
    // Add overhead for role, etc.
    total += 10;
  }
  return total;
}

// ============================================================================
// Token Budget
// ============================================================================

/**
 * Create a token budget
 */
export function createTokenBudget(maxTokens: number): TokenBudget {
  return {
    max: maxTokens,
    used: 0,
    reserved: {
      systemPrompt: 0,
      responseBuffer: Math.floor(maxTokens * 0.2), // Reserve 20% for response
      toolResults: Math.floor(maxTokens * 0.1),    // Reserve 10% for pending tools
    },
  };
}

/**
 * Get available tokens
 */
export function getAvailableTokens(budget: TokenBudget): number {
  const reserved = Object.values(budget.reserved).reduce((a, b) => a + b, 0);
  return Math.max(0, budget.max - budget.used - reserved);
}

/**
 * Check if content fits in budget
 */
export function canFitInBudget(budget: TokenBudget, content: string): boolean {
  const tokens = estimateTokens(content);
  return tokens <= getAvailableTokens(budget);
}

/**
 * Update budget with used tokens
 */
export function updateBudget(budget: TokenBudget, tokens: number): TokenBudget {
  return {
    ...budget,
    used: budget.used + tokens,
  };
}

/**
 * Get budget usage percentage
 */
export function getBudgetUsage(budget: TokenBudget): number {
  return budget.used / budget.max;
}

// ============================================================================
// Working Memory
// ============================================================================

/**
 * Create a working memory store
 */
export function createWorkingMemory(): WorkingMemory {
  const entries = new Map<string, WorkingMemoryEntry>();

  return {
    entries,

    store(id: string, entry: Omit<WorkingMemoryEntry, "id">): void {
      entries.set(id, { id, ...entry });
    },

    retrieve(ids: string[]): string {
      const relevant: WorkingMemoryEntry[] = [];
      for (const id of ids) {
        const entry = entries.get(id);
        if (entry) {
          relevant.push(entry);
        }
      }

      if (relevant.length === 0) return "";

      return relevant
        .sort((a, b) => b.timestamp - a.timestamp)
        .map((e) => `### ${e.id}\n${e.summary}`)
        .join("\n\n");
    },

    search(query: string, limit = 5): WorkingMemoryEntry[] {
      const queryLower = query.toLowerCase();
      const scored: { entry: WorkingMemoryEntry; score: number }[] = [];

      for (const entry of entries.values()) {
        // Simple keyword matching
        const summaryLower = entry.summary.toLowerCase();
        let score = 0;

        for (const word of queryLower.split(/\s+/)) {
          if (summaryLower.includes(word)) {
            score += 1;
          }
        }

        if (score > 0) {
          scored.push({ entry, score });
        }
      }

      return scored
        .sort((a, b) => b.score - a.score)
        .slice(0, limit)
        .map((s) => s.entry);
    },

    prune(maxAgeMs = 30 * 60 * 1000): number {
      const now = Date.now();
      let pruned = 0;

      for (const [id, entry] of entries) {
        if (now - entry.timestamp > maxAgeMs) {
          entries.delete(id);
          pruned++;
        }
      }

      return pruned;
    },
  };
}

// ============================================================================
// Context Summarization
// ============================================================================

const SUMMARIZE_PROMPT = `Summarize the following tool results concisely.
Keep: errors, key findings, file paths created/modified, important values.
Drop: verbose output, duplicate info, formatting noise.

Tool Results:
{results}

Summary (2-3 sentences max):`;

/**
 * Summarize tool results
 */
export async function summarizeToolResults(
  results: { tool: string; result: string }[],
  llmCall: LLMCaller
): Promise<string> {
  const resultsText = results
    .map((r) => `[${r.tool}]\n${r.result}`)
    .join("\n\n");

  const prompt = SUMMARIZE_PROMPT.replace("{results}", resultsText);

  try {
    const response = await llmCall({
      messages: [
        { role: "system", content: "You are summarizing tool results. Be concise." },
        { role: "user", content: prompt },
      ],
      maxTokens: 300,
    });

    return response.content.trim();
  } catch {
    // Fallback: just truncate
    return results.map((r) => `${r.tool}: completed`).join("; ");
  }
}

const WORK_SESSION_PROMPT = `Summarize what was accomplished in this work session.

Tasks completed: {tasks}
Tools used: {tools}
Files affected: {files}

Create a brief summary covering:
1. What was done
2. Key outcomes
3. What's still pending (if any)

Summary:`;

/**
 * Summarize a work session
 */
export async function summarizeWorkSession(
  tasks: string[],
  toolsUsed: string[],
  filesAffected: string[],
  llmCall: LLMCaller
): Promise<string> {
  const prompt = WORK_SESSION_PROMPT
    .replace("{tasks}", tasks.join(", ") || "none")
    .replace("{tools}", [...new Set(toolsUsed)].join(", ") || "none")
    .replace("{files}", filesAffected.join(", ") || "none");

  try {
    const response = await llmCall({
      messages: [
        { role: "system", content: "You are summarizing a work session. Be concise." },
        { role: "user", content: prompt },
      ],
      maxTokens: 400,
    });

    return response.content.trim();
  } catch {
    return `Completed ${tasks.length} tasks using ${toolsUsed.length} tools.`;
  }
}

// ============================================================================
// Context Pruning
// ============================================================================

export interface PruneRules {
  keepLastMessages: number;
  keepRecentMs: number;
  alwaysKeepTypes: string[];
  pruneToolResultsAfterMs: number;
  summarizeBeforePrune: boolean;
}

export const DEFAULT_PRUNE_RULES: PruneRules = {
  keepLastMessages: 10,
  keepRecentMs: 300000, // 5 minutes
  alwaysKeepTypes: ["plan", "error", "human_input"],
  pruneToolResultsAfterMs: 60000, // 1 minute
  summarizeBeforePrune: true,
};

interface TaggedMessage extends AgentMessage {
  timestamp?: number;
  type?: string;
}

/**
 * Apply pruning rules to messages
 */
export function applyPruneRules(
  messages: TaggedMessage[],
  rules: PruneRules = DEFAULT_PRUNE_RULES
): { kept: TaggedMessage[]; pruned: TaggedMessage[] } {
  const now = Date.now();
  const kept: TaggedMessage[] = [];
  const pruned: TaggedMessage[] = [];

  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    const age = now - (msg.timestamp ?? now);
    const isRecent = age < rules.keepRecentMs;
    const isLastN = i >= messages.length - rules.keepLastMessages;
    const isProtected = rules.alwaysKeepTypes.includes(msg.type ?? "");

    if (isRecent || isLastN || isProtected) {
      kept.push(msg);
    } else if (
      msg.role === "assistant" &&
      msg.type === "tool_result" &&
      age > rules.pruneToolResultsAfterMs
    ) {
      pruned.push(msg);
    } else {
      kept.push(msg);
    }
  }

  return { kept, pruned };
}

// ============================================================================
// Proactive Context Management
// ============================================================================

/**
 * Check if context management is needed
 */
export function shouldManageContext(
  budget: TokenBudget,
  iterationCount: number,
  config: ContextConfig
): boolean {
  if (!config.proactiveManagement) return false;

  const usage = getBudgetUsage(budget);

  // Trigger at threshold
  if (usage > config.contextThreshold) return true;

  // Trigger at iteration interval
  if (iterationCount > 0 && iterationCount % config.summarizeAfterIterations === 0) {
    return true;
  }

  return false;
}

/**
 * Manage context proactively
 */
export async function manageContext(
  messages: TaggedMessage[],
  budget: TokenBudget,
  workingMemory: WorkingMemory,
  config: ContextConfig,
  llmCall?: LLMCaller
): Promise<{
  messages: TaggedMessage[];
  budget: TokenBudget;
  summarized?: string;
}> {
  // Apply pruning rules
  const { kept, pruned } = applyPruneRules(messages);

  let summarized: string | undefined;

  // Summarize pruned content if configured and LLM available
  if (pruned.length > 0 && DEFAULT_PRUNE_RULES.summarizeBeforePrune && llmCall) {
    const toolResults = pruned
      .filter((m) => m.type === "tool_result")
      .map((m) => ({
        tool: "tool",
        result: typeof m.content === "string" ? m.content : JSON.stringify(m.content),
      }));

    if (toolResults.length > 0) {
      summarized = await summarizeToolResults(toolResults, llmCall);

      // Store summary in working memory
      workingMemory.store(`summary_${Date.now()}`, {
        summary: summarized,
        timestamp: Date.now(),
      });
    }
  }

  // Recalculate budget
  const newUsed = estimateMessageTokens(kept);
  const newBudget: TokenBudget = {
    ...budget,
    used: newUsed,
  };

  // Add summary as system message if significant content was pruned
  if (summarized && pruned.length > 2) {
    kept.push({
      role: "system",
      content: `## Previous Work Summary\n${summarized}`,
      timestamp: Date.now(),
      type: "summary",
    });
  }

  return {
    messages: kept,
    budget: newBudget,
    summarized,
  };
}

// ============================================================================
// Context Injection
// ============================================================================

/**
 * Build context from working memory for a new subtask
 */
export function buildWorkingMemoryContext(
  workingMemory: WorkingMemory,
  dependencyIds: string[]
): string {
  if (dependencyIds.length === 0) return "";

  const context = workingMemory.retrieve(dependencyIds);
  if (!context) return "";

  return `## Context from Previous Work\n${context}`;
}

/**
 * Search working memory for relevant context
 */
export function searchRelevantContext(
  workingMemory: WorkingMemory,
  query: string,
  limit = 3
): string {
  const entries = workingMemory.search(query, limit);
  if (entries.length === 0) return "";

  const context = entries
    .map((e) => `### ${e.id}\n${e.summary}`)
    .join("\n\n");

  return `## Related Context\n${context}`;
}

/**
 * Context Summarization
 * 
 * Manages context window by summarizing old content when
 * the conversation history grows too long.
 */

import type { LLMCaller } from "../types.js";

// ============================================================================
// Types
// ============================================================================

export interface Message {
  role: "user" | "assistant" | "system" | "tool";
  content: string;
  toolName?: string;
  toolResult?: unknown;
  timestamp?: number;
}

export interface SummarizerConfig {
  /** Enable automatic summarization */
  enabled: boolean;
  /** Target token count after summarization */
  targetTokens: number;
  /** Trigger summarization when exceeding this */
  thresholdTokens: number;
  /** Minimum messages to keep unsummarized */
  keepRecentMessages: number;
  /** Include tool results in summary */
  summarizeToolResults: boolean;
}

export interface SummarizationResult {
  summarized: boolean;
  summary?: string;
  removedMessages: number;
  originalTokens: number;
  finalTokens: number;
  savedTokens: number;
}

export interface ContextState {
  messages: Message[];
  summaries: ContextSummary[];
  totalTokensEstimate: number;
}

export interface ContextSummary {
  id: string;
  createdAt: number;
  messageRange: { from: number; to: number };
  summary: string;
  keyPoints: string[];
  tokensSaved: number;
}

// ============================================================================
// Token Estimation
// ============================================================================

/**
 * Rough token estimation (4 chars ≈ 1 token)
 */
export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

export function estimateMessageTokens(message: Message): number {
  let tokens = estimateTokens(message.content);
  tokens += 4; // Role overhead
  if (message.toolName) tokens += estimateTokens(message.toolName) + 2;
  if (message.toolResult) tokens += estimateTokens(JSON.stringify(message.toolResult));
  return tokens;
}

export function estimateTotalTokens(messages: Message[]): number {
  return messages.reduce((sum, m) => sum + estimateMessageTokens(m), 0);
}

// ============================================================================
// Context Summarizer
// ============================================================================

const DEFAULT_CONFIG: SummarizerConfig = {
  enabled: true,
  targetTokens: 50000,
  thresholdTokens: 80000,
  keepRecentMessages: 10,
  summarizeToolResults: true,
};

export class ContextSummarizer {
  private config: SummarizerConfig;
  private llmCaller?: LLMCaller;
  private summaries: ContextSummary[] = [];

  constructor(config: Partial<SummarizerConfig> = {}, llmCaller?: LLMCaller) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.llmCaller = llmCaller;
  }

  /**
   * Check if summarization is needed
   */
  needsSummarization(messages: Message[]): boolean {
    if (!this.config.enabled) return false;
    const totalTokens = estimateTotalTokens(messages);
    return totalTokens > this.config.thresholdTokens;
  }

  /**
   * Summarize older messages to reduce context size
   */
  async summarize(messages: Message[]): Promise<SummarizationResult> {
    const originalTokens = estimateTotalTokens(messages);

    if (!this.needsSummarization(messages)) {
      return {
        summarized: false,
        removedMessages: 0,
        originalTokens,
        finalTokens: originalTokens,
        savedTokens: 0,
      };
    }

    // Determine how many messages to summarize
    const keepCount = Math.max(this.config.keepRecentMessages, 3);
    const recentMessages = messages.slice(-keepCount);
    const olderMessages = messages.slice(0, -keepCount);

    if (olderMessages.length < 3) {
      // Not enough to summarize meaningfully
      return {
        summarized: false,
        removedMessages: 0,
        originalTokens,
        finalTokens: originalTokens,
        savedTokens: 0,
      };
    }

    // Generate summary
    const summary = await this.generateSummary(olderMessages);

    // Create summary record
    const summaryRecord: ContextSummary = {
      id: `sum_${Date.now()}`,
      createdAt: Date.now(),
      messageRange: { from: 0, to: olderMessages.length - 1 },
      summary: summary.text,
      keyPoints: summary.keyPoints,
      tokensSaved: estimateTotalTokens(olderMessages) - estimateTokens(summary.text),
    };

    this.summaries.push(summaryRecord);

    const finalTokens = estimateTokens(summary.text) + estimateTotalTokens(recentMessages);

    return {
      summarized: true,
      summary: summary.text,
      removedMessages: olderMessages.length,
      originalTokens,
      finalTokens,
      savedTokens: originalTokens - finalTokens,
    };
  }

  /**
   * Get summary to inject as context
   */
  getSummaryContext(): string {
    if (this.summaries.length === 0) return "";

    const latest = this.summaries[this.summaries.length - 1];
    return `
## Previous Conversation Summary

${latest.summary}

### Key Points
${latest.keyPoints.map(p => `- ${p}`).join("\n")}

_This summarizes ${latest.messageRange.to - latest.messageRange.from + 1} earlier messages._
`.trim();
  }

  /**
   * Condense tool results to save tokens
   */
  condenseToolResult(result: unknown, maxTokens: number = 500): string {
    const str = typeof result === "string" ? result : JSON.stringify(result, null, 2);
    const tokens = estimateTokens(str);

    if (tokens <= maxTokens) return str;

    // Truncate intelligently
    const lines = str.split("\n");
    let condensed = "";
    let currentTokens = 0;

    for (const line of lines) {
      const lineTokens = estimateTokens(line);
      if (currentTokens + lineTokens > maxTokens - 50) {
        condensed += "\n... [truncated] ...";
        break;
      }
