/**
 * Tool Interception with Timed Approval Gates
 * 
 * Intercepts risky tool calls, emits approval requests,
 * and either waits for human response or proceeds after timeout.
 */

import type { ToolCall } from "../types.js";

// ============================================================================
// Types
// ============================================================================

export type RiskLevel = "low" | "medium" | "high" | "critical";
export type ApprovalDecision = "approved" | "denied" | "timeout" | "pending";

export interface ApprovalRequest {
  id: string;
  tool: ToolCall;
  riskLevel: RiskLevel;
  riskReason: string;
  createdAt: number;
  timeoutMs: number;
  decision: ApprovalDecision;
  decidedAt?: number;
  decidedBy?: "human" | "timeout" | "auto";
}

export interface ApprovalGateConfig {
  /** Enable approval gates */
  enabled: boolean;
  /** Timeout before auto-proceeding (ms) */
  timeoutMs: number;
  /** Risk levels that require approval */
  requireApprovalFor: RiskLevel[];
  /** Auto-approve low-risk operations */
  autoApproveLowRisk: boolean;
  /** Auto-deny critical operations (require explicit approval) */
  autoDenyCritical: boolean;
  /** Callback when approval is needed */
  onApprovalNeeded?: (request: ApprovalRequest) => void;
  /** Callback when decision is made */
  onDecision?: (request: ApprovalRequest) => void;
}

export interface ApprovalResult {
  proceed: boolean;
  decision: ApprovalDecision;
  request: ApprovalRequest;
  waitedMs: number;
}

// ============================================================================
// Risk Classification
// ============================================================================

const TOOL_RISK_LEVELS: Record<string, RiskLevel> = {
  // Low risk - read-only
  Read: "low",
  web_search: "low",
  web_fetch: "low",
  image: "low",
  session_status: "low",
  sessions_list: "low",
  sessions_history: "low",
  agents_list: "low",

  // Medium risk - local side effects
  Write: "medium",
  Edit: "medium",
  exec: "medium", // Elevated based on command

  // High risk - external effects
  message: "high",
  browser: "high",
  sessions_send: "high",
  sessions_spawn: "high",
  cron: "high",

  // Critical - system changes
  gateway: "critical",
};

const DANGEROUS_PATTERNS = [
  { pattern: /rm\s+-rf/i, level: "critical" as RiskLevel, reason: "Recursive delete" },
  { pattern: /drop\s+(table|database)/i, level: "critical" as RiskLevel, reason: "Database drop" },
  { pattern: /truncate/i, level: "critical" as RiskLevel, reason: "Data truncation" },
  { pattern: /mkfs|format/i, level: "critical" as RiskLevel, reason: "Disk format" },
  { pattern: /dd\s+if=/i, level: "critical" as RiskLevel, reason: "Direct disk write" },
  { pattern: /:(){ :|:& };:/i, level: "critical" as RiskLevel, reason: "Fork bomb" },
  { pattern: />\s*\/dev\/(sda|hda|nvme)/i, level: "critical" as RiskLevel, reason: "Direct device write" },
  { pattern: /chmod\s+777/i, level: "high" as RiskLevel, reason: "Insecure permissions" },
  { pattern: /curl.*\|\s*(bash|sh)/i, level: "high" as RiskLevel, reason: "Piped script execution" },
  { pattern: /git\s+push.*--force/i, level: "high" as RiskLevel, reason: "Force push" },
  { pattern: /npm\s+publish/i, level: "high" as RiskLevel, reason: "Package publish" },
  { pattern: /docker\s+push/i, level: "high" as RiskLevel, reason: "Image publish" },
  { pattern: /kubectl\s+delete/i, level: "high" as RiskLevel, reason: "K8s resource deletion" },
  { pattern: /terraform\s+destroy/i, level: "high" as RiskLevel, reason: "Infrastructure destroy" },
];

export function classifyToolRisk(tool: ToolCall): { level: RiskLevel; reason: string } {
  const baseLevel = TOOL_RISK_LEVELS[tool.name] ?? "medium";
  let level = baseLevel;
  let reason = `Tool type: ${tool.name}`;

  // Special handling for exec
  if (tool.name === "exec" && tool.arguments?.command) {
    const cmd = String(tool.arguments.command);

    for (const { pattern, level: patternLevel, reason: patternReason } of DANGEROUS_PATTERNS) {
      if (pattern.test(cmd)) {
        // Upgrade to more dangerous level
        if (riskOrdinal(patternLevel) > riskOrdinal(level)) {
          level = patternLevel;
          reason = patternReason;
        }
      }
    }
  }

  // Browser actions
  if (tool.name === "browser" && tool.arguments?.action) {
    const action = String(tool.arguments.action);
    if (["act", "click", "type"].includes(action)) {
      level = "high";
      reason = `Browser interaction: ${action}`;
    }
  }

  // Message sending
  if (tool.name === "message" && tool.arguments?.action === "send") {
    level = "high";
    reason = "External message";
  }

  return { level, reason };
}

function riskOrdinal(level: RiskLevel): number {
  return { low: 0, medium: 1, high: 2, critical: 3 }[level];
}

// ============================================================================
// Approval Gate
// ============================================================================

const DEFAULT_CONFIG: ApprovalGateConfig = {
  enabled: true,
  timeoutMs: 10000, // 10 seconds
  requireApprovalFor: ["high", "critical"],
  autoApproveLowRisk: true,
  autoDenyCritical: false,
};

export class ApprovalGate {
  private config: ApprovalGateConfig;
  private pendingRequests: Map<string, ApprovalRequest> = new Map();
  private resolvers: Map<string, (decision: ApprovalDecision) => void> = new Map();

  constructor(config: Partial<ApprovalGateConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Check if a tool call requires approval
   */
  requiresApproval(tool: ToolCall): boolean {
    if (!this.config.enabled) return false;

    const { level } = classifyToolRisk(tool);
    return this.config.requireApprovalFor.includes(level);
  }

  /**
   * Request approval for a tool call
   * Returns a promise that resolves when approved, denied, or timed out
   */
  async requestApproval(tool: ToolCall): Promise<ApprovalResult> {
    const { level, reason } = classifyToolRisk(tool);
    const startTime = Date.now();

    // Auto-approve low risk
    if (this.config.autoApproveLowRisk && level === "low") {
      return {
        proceed: true,
        decision: "approved",
        request: this.createRequest(tool, level, reason, "approved"),
        waitedMs: 0,
      };
    }

    // Auto-deny critical if configured
    if (this.config.autoDenyCritical && level === "critical") {
      const request = this.createRequest(tool, level, reason, "denied");
      request.decidedBy = "auto";
      return {
        proceed: false,
        decision: "denied",
        request,
        waitedMs: 0,
      };
    }

    // Create pending request
    const request = this.createRequest(tool, level, reason, "pending");
    this.pendingRequests.set(request.id, request);

    // Notify listeners
    this.config.onApprovalNeeded?.(request);

    // Wait for decision or timeout
    const decision = await this.waitForDecision(request);
    const waitedMs = Date.now() - startTime;

    // Update request
    request.decision = decision;
    request.decidedAt = Date.now();
    request.decidedBy = decision === "timeout" ? "timeout" : "human";

    // Cleanup
    this.pendingRequests.delete(request.id);
    this.resolvers.delete(request.id);

    // Notify listeners
    this.config.onDecision?.(request);

    return {
      proceed: decision === "approved" || decision === "timeout",
      decision,
      request,
      waitedMs,
    };
  }

  /**
   * Approve a pending request
   */
  approve(requestId: string): boolean {
    return this.decide(requestId, "approved");
  }

  /**
   * Deny a pending request
   */
  deny(requestId: string): boolean {
    return this.decide(requestId, "denied");
  }

  /**
   * Get all pending requests
   */
  getPendingRequests(): ApprovalRequest[] {
    return Array.from(this.pendingRequests.values());
  }

  /**
   * Get a specific request
   */
  getRequest(requestId: string): ApprovalRequest | undefined {
    return this.pendingRequests.get(requestId);
  }

  /**
   * Format pending request for display
   */
  formatPendingRequest(request: ApprovalRequest): string {
    const timeLeft = Math.max(0, request.timeoutMs - (Date.now() - request.createdAt));
    const timeLeftSec = Math.round(timeLeft / 1000);

    return `
⚠️ **Approval Required**

**Tool:** ${request.tool.name}
**Risk:** ${request.riskLevel.toUpperCase()} - ${request.riskReason}
**Arguments:** \`${JSON.stringify(request.tool.arguments)}\`

⏱️ Auto-proceeding in ${timeLeftSec}s unless denied.

Reply with:
- \`/approve ${request.id.slice(-6)}\` to approve
- \`/deny ${request.id.slice(-6)}\` to deny
`.trim();
  }

  // ──────────────────────────────────────────────────────────────────────────
  // Private Methods
  // ──────────────────────────────────────────────────────────────────────────

  private createRequest(
    tool: ToolCall,
    riskLevel: RiskLevel,
    riskReason: string,
    decision: ApprovalDecision
  ): ApprovalRequest {
    return {
      id: `apr_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      tool,
      riskLevel,
      riskReason,
      createdAt: Date.now(),
      timeoutMs: this.config.timeoutMs,
      decision,
    };
  }

  private waitForDecision(request: ApprovalRequest): Promise<ApprovalDecision> {
    return new Promise((resolve) => {
      // Store resolver for external decisions
      this.resolvers.set(request.id, resolve);

      // Set timeout
      setTimeout(() => {
        if (this.pendingRequests.has(request.id)) {
          resolve("timeout");
        }
      }, this.config.timeoutMs);
    });
  }

  private decide(requestId: string, decision: ApprovalDecision): boolean {
    const resolver = this.resolvers.get(requestId);
    if (!resolver) return false;

    resolver(decision);
    return true;
  }
}

// ============================================================================
// Factory
// ============================================================================

let defaultGate: ApprovalGate | null = null;

export function getApprovalGate(config?: Partial<ApprovalGateConfig>): ApprovalGate {
  if (!defaultGate) {
    defaultGate = new ApprovalGate(config);
  }
  return defaultGate;
}

export function resetApprovalGate(): void {
  defaultGate = null;
}

// ============================================================================
// Middleware Helper
// ============================================================================

/**
 * Create a tool execution wrapper that applies approval gates
 */
export function withApprovalGate<T>(
  gate: ApprovalGate,
  executor: (tool: ToolCall) => Promise<T>
): (tool: ToolCall) => Promise<T | { blocked: true; reason: string }> {
  return async (tool: ToolCall) => {
    if (!gate.requiresApproval(tool)) {
      return executor(tool);
    }

    const result = await gate.requestApproval(tool);

    if (!result.proceed) {
      return {
        blocked: true,
        reason: `Tool blocked: ${result.decision} (${result.request.riskReason})`,
      };
    }

    return executor(tool);
  };
}

/**
 * Confidence-Gated Autonomy
 * 
 * Assess confidence before risky actions and escalate when appropriate.
 */

import type {
  ToolCall,
  RiskLevel,
  ConfidenceAssessment,
  GateDecision,
  ExecutionConfig,
  LLMCaller,
} from "../types.js";

// ============================================================================
// Risk Classification
// ============================================================================

/**
 * Tool risk levels
 */
const TOOL_RISK_MAP: Record<string, RiskLevel> = {
  // Low risk - read-only, no side effects
  Read: "low",
  web_search: "low",
  web_fetch: "low",
  image: "low",
  session_status: "low",
  sessions_list: "low",
  sessions_history: "low",
  agents_list: "low",

  // Medium risk - reversible side effects
  Write: "medium",
  Edit: "medium",
  exec: "medium", // Depends on command

  // High risk - may be irreversible
  message: "high", // External communication
  browser: "high", // Can click things
  sessions_send: "high",
  sessions_spawn: "high",

  // Critical - definitely irreversible (extend as needed)
  gateway: "high", // Config changes
};

/**
 * Patterns that elevate exec risk
 */
const DANGEROUS_EXEC_PATTERNS = [
  /rm\s+-rf/i,
  /drop\s+(table|database)/i,
  /delete\s+from/i,
  /truncate/i,
  /format\s+/i,
  /mkfs/i,
  /dd\s+if=/i,
];

const ELEVATED_EXEC_PATTERNS = [
  /git\s+push/i,
  /git\s+force/i,
  /npm\s+publish/i,
  /docker\s+push/i,
  /kubectl\s+delete/i,
  /terraform\s+destroy/i,
  /aws\s+.*delete/i,
];

/**
 * Classify the risk level of a tool call
 */
export function classifyRisk(tool: ToolCall): RiskLevel {
  const baseRisk = TOOL_RISK_MAP[tool.name] ?? "medium";

  // Special handling for exec
  if (tool.name === "exec") {
    const cmd = tool.arguments.command as string | undefined;
    if (cmd) {
      if (DANGEROUS_EXEC_PATTERNS.some((p) => p.test(cmd))) {
        return "critical";
      }
      if (ELEVATED_EXEC_PATTERNS.some((p) => p.test(cmd))) {
        return "high";
      }
    }
  }

  // Special handling for message (external comms)
  if (tool.name === "message") {
    return "high";
  }

  // Browser with action can be risky
  if (tool.name === "browser") {
    const action = tool.arguments.action as string | undefined;
    if (action && ["act", "click", "type", "navigate"].includes(action)) {
      return "high";
    }
  }

  return baseRisk;
}

/**
 * Check if a tool is low risk (can proceed without assessment)
 */
export function isLowRisk(tool: ToolCall): boolean {
  return classifyRisk(tool) === "low";
}

// ============================================================================
// Confidence Thresholds
// ============================================================================

export interface ConfidenceThresholds {
  proceedFreely: number;      // High confidence, just do it
  proceedCautiously: number;  // Create checkpoint, then proceed
  askHuman: number;           // Need human input
  refuse: number;             // Don't do without explicit approval
}

export const DEFAULT_THRESHOLDS: ConfidenceThresholds = {
  proceedFreely: 0.9,
  proceedCautiously: 0.7,
  askHuman: 0.5,
  refuse: 0.3,
};

/**
 * Resolve thresholds from config
 */
export function resolveThresholds(config: ExecutionConfig): ConfidenceThresholds {
  // Use config threshold as the "proceed cautiously" level
  // Derive others from it
  const cautious = config.confidenceThreshold;
  return {
    proceedFreely: Math.min(0.95, cautious + 0.2),
    proceedCautiously: cautious,
    askHuman: Math.max(0.3, cautious - 0.2),
    refuse: Math.max(0.1, cautious - 0.4),
  };
}

// ============================================================================
// Confidence Assessment
// ============================================================================

const ASSESSMENT_PROMPT = `Assess your confidence in the proposed action.

Proposed action: {action}
Arguments: {arguments}
Context: {context}

Consider:
1. How certain are you this is the right approach?
2. What could go wrong?
3. Is this reversible?
4. Do you have enough information?

Rate your confidence (0.0-1.0) and explain briefly.

Output valid JSON:
{
  "confidence": 0.0-1.0,
  "reversible": true|false|"partial",
  "reasoning": "Brief explanation",
  "suggestedQuestion": "Question for human if low confidence (optional)"
}`;

/**
 * Assess confidence in an action (via LLM)
 */
export async function assessConfidence(
  tool: ToolCall,
  context: string,
  llmCall: LLMCaller
): Promise<ConfidenceAssessment> {
  const prompt = ASSESSMENT_PROMPT
    .replace("{action}", tool.name)
    .replace("{arguments}", JSON.stringify(tool.arguments, null, 2))
    .replace("{context}", context);

  try {
    const response = await llmCall({
      messages: [
        { role: "system", content: "You are assessing action confidence. Output valid JSON only." },
        { role: "user", content: prompt },
      ],
      maxTokens: 300,
    });

    const parsed = parseJsonFromResponse(response.content);

    if (!parsed) {
      return defaultAssessment(tool);
    }

    return {
      confidence: clamp(Number(parsed.confidence) || 0.5, 0, 1),
      reversible: (parsed.reversible as boolean | "partial") ?? false,
      reasoning: String(parsed.reasoning ?? "No reasoning provided"),
      suggestedQuestion: parsed.suggestedQuestion as string | undefined,
    };
  } catch {
    return defaultAssessment(tool);
  }
}

/**
 * Quick confidence assessment without LLM (heuristic-based)
 */
export function quickAssessConfidence(tool: ToolCall): ConfidenceAssessment {
  const risk = classifyRisk(tool);

  const confidenceByRisk: Record<RiskLevel, number> = {
    low: 0.95,
    medium: 0.75,
    high: 0.55,
    critical: 0.3,
  };

  const reversibleByRisk: Record<RiskLevel, boolean | "partial"> = {
    low: true,
    medium: true,
    high: "partial",
    critical: false,
  };

  return {
    confidence: confidenceByRisk[risk],
    reversible: reversibleByRisk[risk],
    reasoning: `Risk level: ${risk}`,
  };
}

function defaultAssessment(tool: ToolCall): ConfidenceAssessment {
  const risk = classifyRisk(tool);
  return {
    confidence: risk === "low" ? 0.9 : risk === "medium" ? 0.7 : 0.5,
    reversible: risk !== "critical",
    reasoning: "Default assessment based on tool type",
  };
}

// ============================================================================
// Gate Decision
// ============================================================================

/**
 * Make a gate decision based on confidence assessment
 */
export function makeGateDecision(
  assessment: ConfidenceAssessment,
  thresholds: ConfidenceThresholds
): GateDecision {
  if (assessment.confidence >= thresholds.proceedFreely) {
    return { proceed: true, checkpoint: false };
  }

  if (assessment.confidence >= thresholds.proceedCautiously) {
    return {
      proceed: true,
      checkpoint: true,
      reason: assessment.reasoning,
    };
  }

  if (assessment.confidence >= thresholds.askHuman) {
    return {
      proceed: false,
      waitForHuman: true,
      question: assessment.suggestedQuestion ?? 
        `Confidence is ${(assessment.confidence * 100).toFixed(0)}%. Should I proceed?`,
      options: ["Yes, proceed", "No, cancel", "Modify approach"],
    };
  }

  return {
    proceed: false,
    refused: true,
    reason: `Confidence too low (${(assessment.confidence * 100).toFixed(0)}%): ${assessment.reasoning}`,
  };
}

/**
 * Full gate check: assess and decide
 */
export async function gateAction(
  tool: ToolCall,
  context: string,
  config: ExecutionConfig,
  llmCall?: LLMCaller
): Promise<{ assessment: ConfidenceAssessment; decision: GateDecision }> {
  if (!config.confidenceGates) {
    // Gates disabled, always proceed
    return {
      assessment: { confidence: 1, reversible: true, reasoning: "Gates disabled" },
      decision: { proceed: true, checkpoint: false },
    };
  }

  // Skip assessment for low-risk tools
  if (isLowRisk(tool)) {
    const assessment = quickAssessConfidence(tool);
    return {
      assessment,
      decision: { proceed: true, checkpoint: false },
    };
  }

  // Full assessment
  const assessment = llmCall
    ? await assessConfidence(tool, context, llmCall)
    : quickAssessConfidence(tool);

  const thresholds = resolveThresholds(config);
  const decision = makeGateDecision(assessment, thresholds);

  return { assessment, decision };
}

// ============================================================================
// Checkpointing
// ============================================================================

export interface Checkpoint {
  id: string;
  timestamp: number;
  tool: ToolCall;
  context: string;
  files?: { path: string; content: string }[];
}

/**
 * Create a checkpoint before a risky action
 */
export async function createCheckpoint(
  tool: ToolCall,
  context: string,
  readFile?: (path: string) => Promise<string | null>
): Promise<Checkpoint> {
  const checkpoint: Checkpoint = {
    id: `ckpt_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
    timestamp: Date.now(),
    tool,
    context,
  };

  // For file operations, snapshot the file
  if (readFile && (tool.name === "Write" || tool.name === "Edit")) {
    const path = tool.arguments.path as string | undefined;
    if (path) {
      try {
        const content = await readFile(path);
        if (content !== null) {
          checkpoint.files = [{ path, content }];
        }
      } catch {
        // File doesn't exist, no snapshot needed
      }
    }
  }

  return checkpoint;
}

// ============================================================================
// Utilities
// ============================================================================

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function parseJsonFromResponse(content: string): Record<string, unknown> | null {
  try {
    return JSON.parse(content);
  } catch {
    const match = content.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (match) {
      try {
        return JSON.parse(match[1]);
      } catch {
        return null;
      }
    }
    return null;
  }
}

/**
 * Semantic Error Recovery
 * 
 * Diagnose errors and adapt approach instead of simple retry.
 */

import type {
  ToolCall,
  ToolResult,
  ErrorDiagnosis,
  RecoveryStrategy,
  ErrorRecoveryConfig,
  LLMCaller,
} from "../types.js";

// ============================================================================
// Error Pattern Matching
// ============================================================================

interface ErrorPattern {
  match: RegExp;
  strategy: (tool: ToolCall, error: string) => RecoveryStrategy;
}

/**
 * File operation error patterns
 */
const FILE_ERROR_PATTERNS: ErrorPattern[] = [
  {
    match: /ENOENT|no such file|file not found/i,
    strategy: (tool, _error) => {
      if (tool.name === "Read") {
        return {
          type: "alternative_approach",
          newPlan: `File ${tool.arguments.path} doesn't exist. Check if we need to create it first or use a different path.`,
        };
      }
      if (tool.name === "Edit") {
        return {
          type: "retry_modified",
          modifiedArgs: { ...tool.arguments, createIfMissing: true },
        };
      }
      return { type: "escalate", explanation: "File not found" };
    },
  },
  {
    match: /EACCES|permission denied/i,
    strategy: () => ({
      type: "alternative_approach",
      newPlan: "Permission denied. Try with elevated privileges or use a different location.",
    }),
  },
  {
    match: /ENOSPC|no space left/i,
    strategy: () => ({
      type: "escalate",
      explanation: "Disk full. Cannot continue without human intervention.",
    }),
  },
  {
    match: /EEXIST|already exists/i,
    strategy: (tool) => ({
      type: "alternative_approach",
      newPlan: `File/directory ${tool.arguments.path} already exists. Decide whether to overwrite, rename, or skip.`,
    }),
  },
  {
    match: /EISDIR|is a directory/i,
    strategy: () => ({
      type: "alternative_approach",
      newPlan: "Target is a directory, not a file. Adjust the path.",
    }),
  },
];

/**
 * Network error patterns
 */
const NETWORK_ERROR_PATTERNS: ErrorPattern[] = [
  {
    match: /ETIMEDOUT|timeout|timed out/i,
    strategy: () => ({
      type: "retry_same",
      delay: 5000,
    }),
  },
  {
    match: /ECONNREFUSED|connection refused/i,
    strategy: (tool) => ({
      type: "alternative_approach",
      newPlan: `Service is not running or refusing connections. Check if it needs to be started.`,
    }),
  },
  {
    match: /ENOTFOUND|getaddrinfo|DNS/i,
    strategy: () => ({
      type: "alternative_approach",
      newPlan: "DNS resolution failed. Check the hostname or network connectivity.",
    }),
  },
  {
    match: /404|not found/i,
    strategy: (tool) => ({
      type: "alternative_approach",
      newPlan: `Resource not found. Verify the URL or search for the correct endpoint.`,
    }),
  },
  {
    match: /401|unauthorized/i,
    strategy: () => ({
      type: "escalate",
      explanation: "Authentication required. Need credentials.",
    }),
  },
  {
    match: /403|forbidden/i,
    strategy: () => ({
      type: "escalate",
      explanation: "Access forbidden. Need different permissions.",
    }),
  },
  {
    match: /429|rate limit|too many requests/i,
    strategy: () => ({
      type: "retry_same",
      delay: 60000, // Wait 1 minute
    }),
  },
  {
    match: /5\d{2}|server error|internal error/i,
    strategy: () => ({
      type: "retry_same",
      delay: 10000,
    }),
  },
];

/**
 * Exec/command error patterns
 */
const EXEC_ERROR_PATTERNS: ErrorPattern[] = [
  {
    match: /command not found|not recognized/i,
    strategy: (tool) => {
      const cmd = (tool.arguments.command as string)?.split(" ")[0] ?? "command";
      return {
        type: "alternative_approach",
        newPlan: `Command '${cmd}' not installed. Try installing it or use an alternative.`,
      };
    },
  },
  {
    match: /npm ERR!.*ERESOLVE/i,
    strategy: () => ({
      type: "retry_modified",
      modifiedArgs: { command: "npm install --legacy-peer-deps" },
    }),
  },
  {
    match: /git.*conflict/i,
    strategy: () => ({
      type: "escalate",
      explanation: "Git merge conflict requires manual resolution.",
    }),
  },
  {
    match: /git.*diverged/i,
    strategy: () => ({
      type: "alternative_approach",
      newPlan: "Git branches have diverged. Need to decide whether to merge, rebase, or force push.",
    }),
  },
  {
    match: /docker.*no such image/i,
    strategy: () => ({
      type: "alternative_approach",
      newPlan: "Docker image not found. Need to build or pull it first.",
    }),
  },
  {
    match: /syntax error|parse error/i,
    strategy: () => ({
      type: "alternative_approach",
      newPlan: "Syntax error in command or script. Review and fix the syntax.",
    }),
  },
];

/**
 * All error patterns
 */
const ALL_ERROR_PATTERNS: ErrorPattern[] = [
  ...FILE_ERROR_PATTERNS,
  ...NETWORK_ERROR_PATTERNS,
  ...EXEC_ERROR_PATTERNS,
];

/**
 * Try to match error against known patterns
 */
function matchErrorPattern(
  tool: ToolCall,
  error: string
): RecoveryStrategy | null {
  for (const pattern of ALL_ERROR_PATTERNS) {
    if (pattern.match.test(error)) {
      return pattern.strategy(tool, error);
    }
  }
  return null;
}

// ============================================================================
// LLM-Based Diagnosis
// ============================================================================

const DIAGNOSIS_PROMPT = `A tool call failed. Diagnose the cause and suggest recovery.

Tool: {toolName}
Arguments: {arguments}
Error: {error}

Analyze:
1. What likely caused this error?
2. Is this recoverable?
3. What alternative approaches could work?
4. Should we skip this and continue, or is it blocking?

Output valid JSON:
{
  "cause": "Brief diagnosis",
  "recoverable": true|false|"maybe",
  "strategy": "alternative_approach"|"retry_modified"|"skip_and_continue"|"escalate"|"retry_same",
  "alternative": "If alternative_approach, describe the new approach",
  "modifiedArgs": {},  // If retry_modified, the new arguments
  "skipReason": "If skip_and_continue, explain why it's safe",
  "escalateExplanation": "If escalate, explain why human needed",
  "retryDelay": 0  // If retry_same, delay in ms
}`;

/**
 * Diagnose error using LLM
 */
async function llmDiagnose(
  tool: ToolCall,
  error: string,
  llmCall: LLMCaller
): Promise<ErrorDiagnosis> {
  const prompt = DIAGNOSIS_PROMPT
    .replace("{toolName}", tool.name)
    .replace("{arguments}", JSON.stringify(tool.arguments, null, 2))
    .replace("{error}", error);

  try {
    const response = await llmCall({
      messages: [
        { role: "system", content: "You are diagnosing tool errors. Output valid JSON only." },
        { role: "user", content: prompt },
      ],
      maxTokens: 500,
    });

    const parsed = parseJsonFromResponse(response.content);

    if (!parsed) {
      return defaultDiagnosis(error);
    }

    const strategy = parseStrategy(parsed);

    return {
      cause: String(parsed.cause ?? "Unknown cause"),
      recoverable: (parsed.recoverable as boolean | "maybe") ?? "maybe",
      strategy,
    };
  } catch {
    return defaultDiagnosis(error);
  }
}

function parseStrategy(parsed: Record<string, unknown>): RecoveryStrategy {
  switch (parsed.strategy) {
    case "alternative_approach":
      return {
        type: "alternative_approach",
        newPlan: (parsed.alternative as string) ?? "Try a different approach",
      };
    case "retry_modified":
      return {
        type: "retry_modified",
        modifiedArgs: (parsed.modifiedArgs as Record<string, unknown>) ?? {},
      };
    case "skip_and_continue":
      return {
        type: "skip_and_continue",
        reason: (parsed.skipReason as string) ?? "Error is non-blocking",
      };
    case "escalate":
      return {
        type: "escalate",
        explanation: (parsed.escalateExplanation as string) ?? "Human intervention needed",
      };
    case "retry_same":
    default:
      return {
        type: "retry_same",
        delay: (parsed.retryDelay as number) ?? 1000,
      };
  }
}

function defaultDiagnosis(error: string): ErrorDiagnosis {
  return {
    cause: error,
    recoverable: "maybe",
    strategy: { type: "escalate", explanation: error },
  };
}

// ============================================================================
// Main Recovery Function
// ============================================================================

/**
 * Diagnose and get recovery strategy
 */
export async function diagnoseAndRecover(
  tool: ToolCall,
  result: ToolResult,
  config: ErrorRecoveryConfig,
  llmCall?: LLMCaller
): Promise<ErrorDiagnosis> {
  if (!config.enabled) {
    return {
      cause: result.error ?? "Unknown error",
      recoverable: false,
      strategy: { type: "escalate", explanation: result.error ?? "Error recovery disabled" },
    };
  }

  const error = result.error ?? "Unknown error";

  // First, try pattern matching (fast)
  const patternStrategy = matchErrorPattern(tool, error);
  if (patternStrategy) {
    return {
      cause: error,
      recoverable: patternStrategy.type !== "escalate",
      strategy: patternStrategy,
    };
  }

  // Then, try LLM diagnosis (if available)
  if (llmCall) {
    return llmDiagnose(tool, error, llmCall);
  }

  // Fallback
  return defaultDiagnosis(error);
}

// ============================================================================
// Recovery Execution
// ============================================================================

/**
 * Execute tool with recovery attempts
 */
export async function executeWithRecovery(
  tool: ToolCall,
  executor: (tool: ToolCall) => Promise<ToolResult>,
  config: ErrorRecoveryConfig,
  llmCall?: LLMCaller
): Promise<{ result: ToolResult; diagnosis?: ErrorDiagnosis; attempts: number }> {
  let attempts = 0;
  let currentTool = tool;
  const tried = new Set<string>();

  while (attempts < config.maxAttempts) {
    attempts++;
    const callSignature = JSON.stringify(currentTool);

    // Prevent infinite loops
    if (tried.has(callSignature)) {
      return {
        result: {
          id: tool.id,
          success: false,
          error: "Recovery loop detected",
        },
        attempts,
      };
    }
    tried.add(callSignature);

    try {
      const result = await executor(currentTool);

      if (result.success) {
        return { result, attempts };
      }

      // Tool returned an error result
      const diagnosis = await diagnoseAndRecover(currentTool, result, config, llmCall);

      switch (diagnosis.strategy.type) {
        case "retry_same":
          if (diagnosis.strategy.delay) {
            await sleep(diagnosis.strategy.delay);
          }
          // currentTool stays the same
          break;

        case "retry_modified":
          currentTool = {
            ...currentTool,
            arguments: { ...currentTool.arguments, ...diagnosis.strategy.modifiedArgs },
          };
          break;

        case "alternative_approach":
          // Can't execute alternative here, return for replanning
          return {
            result: {
              id: tool.id,
              success: false,
              error: result.error,
              needsReplan: true,
              reason: diagnosis.strategy.newPlan,
            },
            diagnosis,
            attempts,
          };

        case "skip_and_continue":
          return {
            result: {
              id: tool.id,
              success: false,
              skipped: true,
              reason: diagnosis.strategy.reason,
            },
            diagnosis,
            attempts,
          };

        case "escalate":
          return {
            result: {
              id: tool.id,
              success: false,
              error: result.error,
              needsHuman: true,
              reason: diagnosis.strategy.explanation,
            },
            diagnosis,
            attempts,
          };
      }
    } catch (err) {
      // Unexpected exception
      const error = err instanceof Error ? err.message : String(err);
      const result: ToolResult = {
        id: tool.id,
        success: false,
        error,
      };

      if (attempts >= config.maxAttempts) {
        return { result, attempts };
      }

      const diagnosis = await diagnoseAndRecover(currentTool, result, config, llmCall);

      if (diagnosis.strategy.type === "escalate") {
        return { result, diagnosis, attempts };
      }

      // Apply non-escalate strategy and continue
      if (diagnosis.strategy.type === "retry_modified") {
        currentTool = {
          ...currentTool,
          arguments: { ...currentTool.arguments, ...diagnosis.strategy.modifiedArgs },
        };
      }
    }
  }

  return {
    result: {
      id: tool.id,
      success: false,
      error: `Failed after ${config.maxAttempts} recovery attempts`,
    },
    attempts,
  };
}

// ============================================================================
// Learning from Errors (optional)
// ============================================================================

export interface ErrorRecord {
  toolName: string;
  errorPattern: string;
  successfulRecovery: RecoveryStrategy;
  timestamp: number;
}

/**
 * Store for learned error patterns
 */
export class ErrorLearningStore {
  private records: ErrorRecord[] = [];
  private maxRecords = 100;

  add(record: ErrorRecord): void {
    this.records.push(record);
    if (this.records.length > this.maxRecords) {
      this.records.shift();
    }
  }

  find(toolName: string, error: string): RecoveryStrategy | null {
    // Find most recent matching record
    for (let i = this.records.length - 1; i >= 0; i--) {
      const record = this.records[i];
      if (
        record.toolName === toolName &&
        error.toLowerCase().includes(record.errorPattern.toLowerCase())
      ) {
        return record.successfulRecovery;
      }
    }
    return null;
  }

  getRecords(): readonly ErrorRecord[] {
    return this.records;
  }

  clear(): void {
    this.records = [];
  }
}

// ============================================================================
// Utilities
// ============================================================================

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseJsonFromResponse(content: string): Record<string, unknown> | null {
  try {
    return JSON.parse(content);
  } catch {
    const match = content.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (match) {
      try {
        return JSON.parse(match[1]);
      } catch {
        return null;
      }
    }
    return null;
  }
}

/**
 * Parallel Tool Execution
 * 
 * Execute independent tools concurrently for speed improvements.
 */

import type {
  ToolCall,
  ToolResult,
  ClassifiedTools,
  ExecutionConfig,
  ToolExecutor,
} from "../types.js";

// ============================================================================
// Tool Classification
// ============================================================================

/**
 * Tools that are known to be read-only (no side effects)
 */
const READ_ONLY_TOOLS = new Set([
  "Read",
  "web_search",
  "web_fetch",
  "image",
  "session_status",
  "sessions_list",
  "sessions_history",
  "agents_list",
  "cron", // cron:list, cron:status
  "nodes", // nodes:status
]);

/**
 * Tools that have side effects and should run sequentially
 */
const SIDE_EFFECT_TOOLS = new Set([
  "Write",
  "Edit",
  "exec",
  "message",
  "browser",
  "cron", // cron:add, cron:remove
  "gateway",
  "sessions_send",
  "sessions_spawn",
  "tts",
]);

/**
 * Check if a tool is read-only (no side effects)
 */
export function isReadOnlyTool(tool: ToolCall): boolean {
  // Direct match
  if (READ_ONLY_TOOLS.has(tool.name)) return true;

  // Check action parameter for tools with mixed behavior
  const action = tool.arguments.action as string | undefined;

  if (tool.name === "cron" && action) {
    return ["status", "list", "runs"].includes(action);
  }

  if (tool.name === "nodes" && action) {
    return ["status", "describe"].includes(action);
  }

  if (tool.name === "browser" && action) {
    return ["status", "snapshot", "screenshot", "tabs"].includes(action);
  }

  // exec with read-only commands
  if (tool.name === "exec") {
    const cmd = tool.arguments.command as string | undefined;
    if (cmd && isReadOnlyCommand(cmd)) return true;
  }

  return false;
}

/**
 * Check if an exec command is read-only
 */
function isReadOnlyCommand(cmd: string): boolean {
  const readOnlyPatterns = [
    /^(ls|cat|head|tail|grep|find|which|echo|pwd|date|whoami|hostname|uname)\b/,
    /^git\s+(status|log|diff|show|branch|remote|tag)\b/,
    /^(npm|yarn|pnpm)\s+(list|outdated|info|view|show)\b/,
    /^docker\s+(ps|images|logs|inspect)\b/,
    /^kubectl\s+(get|describe|logs)\b/,
    /^(file|stat|wc|du|df)\b/,
  ];
  const trimmed = cmd.trim();
  return readOnlyPatterns.some((p) => p.test(trimmed));
}

/**
 * Check if a tool has side effects
 */
export function hasSideEffects(tool: ToolCall): boolean {
  if (isReadOnlyTool(tool)) return false;
  if (SIDE_EFFECT_TOOLS.has(tool.name)) return true;

  // Default: assume side effects for safety
  return true;
}

/**
 * Extract file path from tool arguments
 */
function extractFilePath(tool: ToolCall): string | null {
  const path = tool.arguments.path as string | undefined;
  const filePath = tool.arguments.file_path as string | undefined;
  return path ?? filePath ?? null;
}

/**
 * Check for file path conflicts between tools
 */
function hasFileConflict(a: ToolCall, b: ToolCall): boolean {
  const aPath = extractFilePath(a);
  const bPath = extractFilePath(b);

  if (!aPath || !bPath) return false;

  // Same file = dependency
  if (aPath === bPath) return true;

  // One is parent of other
  if (aPath.startsWith(bPath + "/") || bPath.startsWith(aPath + "/")) {
    return true;
  }

  return false;
}

/**
 * Check if tool B references output from tool A
 */
function referencesOutput(toolB: ToolCall, toolA: ToolCall): boolean {
  const argsStr = JSON.stringify(toolB.arguments);

  // Check for explicit references
  if (argsStr.includes(`{{${toolA.id}}}`)) return true;
  if (argsStr.includes(`result_of_${toolA.name}`)) return true;

  return false;
}

/**
 * Find dependencies for a tool
 */
function findDependencies(tool: ToolCall, previousTools: ToolCall[]): string[] {
  const deps: string[] = [];

  for (const prev of previousTools) {
    // Check output reference
    if (referencesOutput(tool, prev)) {
      deps.push(prev.id);
      continue;
    }

    // Check file conflicts
    if (hasFileConflict(tool, prev)) {
      deps.push(prev.id);
      continue;
    }

    // Write after read on same file
    if (
      (tool.name === "Write" || tool.name === "Edit") &&
      prev.name === "Read" &&
      extractFilePath(tool) === extractFilePath(prev)
    ) {
      deps.push(prev.id);
    }
  }

  return deps;
}

// ============================================================================
// Tool Classification
// ============================================================================

/**
 * Classify tool calls into parallel and sequential groups
 */
export function classifyToolDependencies(
  toolCalls: ToolCall[],
  config: ExecutionConfig
): ClassifiedTools {
  if (!config.parallelTools) {
    // All sequential if parallel disabled
    return {
      parallel: [],
      sequential: toolCalls,
      dependencyGraph: new Map(),
    };
  }

  const graph = new Map<string, string[]>();
  const sequential: ToolCall[] = [];
  const parallel: ToolCall[] = [];

  for (let i = 0; i < toolCalls.length; i++) {
    const tool = toolCalls[i];
    const previousTools = toolCalls.slice(0, i);
    const deps = findDependencies(tool, previousTools);

    if (deps.length > 0) {
      graph.set(tool.id, deps);
      sequential.push(tool);
    } else if (hasSideEffects(tool)) {
      // Side-effecting tools run sequentially for safety
      sequential.push(tool);
    } else {
      parallel.push(tool);
    }
  }

  return { parallel, sequential, dependencyGraph: graph };
}

// ============================================================================
// Parallel Execution
// ============================================================================

/**
 * Execute tools with parallelism where possible
 */
export async function executeToolCalls(
  toolCalls: ToolCall[],
  executor: ToolExecutor,
  config: ExecutionConfig
): Promise<Map<string, ToolResult>> {
  const { parallel, sequential, dependencyGraph } = classifyToolDependencies(
    toolCalls,
    config
  );
  const results = new Map<string, ToolResult>();

  // Execute parallel tools concurrently (with limit)
  if (parallel.length > 0) {
    const parallelResults = await executeParallelWithLimit(
      parallel,
      executor,
      config.maxConcurrentTools
    );
    for (const [id, result] of parallelResults) {
      results.set(id, result);
    }
  }

  // Execute sequential tools in dependency order
  const executed = new Set<string>();

  while (executed.size < sequential.length) {
    // Find tools whose dependencies are satisfied
    const ready = sequential.filter((tool) => {
      if (executed.has(tool.id)) return false;
      const deps = dependencyGraph.get(tool.id) ?? [];
      return deps.every((d) => results.has(d) || executed.has(d));
    });

    if (ready.length === 0 && executed.size < sequential.length) {
      // Circular dependency - execute remaining sequentially
      console.warn("[parallel] Circular dependency detected, falling back to sequential");
      for (const tool of sequential) {
        if (!executed.has(tool.id)) {
          const result = await executor(tool);
          results.set(tool.id, result);
          executed.add(tool.id);
        }
      }
      break;
    }

    // Execute ready tools (could parallelize within this batch too)
    for (const tool of ready) {
      const result = await executor(tool);
      results.set(tool.id, result);
      executed.add(tool.id);
    }
  }

  return results;
}

/**
 * Execute tools in parallel with concurrency limit
 */
async function executeParallelWithLimit(
  tools: ToolCall[],
  executor: ToolExecutor,
  limit: number
): Promise<Map<string, ToolResult>> {
  const results = new Map<string, ToolResult>();

  // Process in batches
  for (let i = 0; i < tools.length; i += limit) {
    const batch = tools.slice(i, i + limit);
    const batchResults = await Promise.allSettled(
      batch.map(async (tool) => {
        const result = await executor(tool);
        return { id: tool.id, result };
      })
    );

    for (const settled of batchResults) {
      if (settled.status === "fulfilled") {
        results.set(settled.value.id, settled.value.result);
      } else {
        // Find the tool that failed
        const tool = batch[batchResults.indexOf(settled)];
        results.set(tool.id, {
          id: tool.id,
          success: false,
          error: settled.reason?.message ?? "Unknown error",
        });
      }
    }
  }

  return results;
}

// ============================================================================
// Metrics
// ============================================================================

export interface ExecutionMetrics {
  totalTools: number;
  parallelBatches: number;
  sequentialTools: number;
  wallTimeMs: number;
  sumToolTimeMs: number;
  speedup: number;
}

/**
 * Execute tools and return metrics
 */
export async function executeWithMetrics(
  toolCalls: ToolCall[],
  executor: ToolExecutor,
  config: ExecutionConfig
): Promise<{ results: Map<string, ToolResult>; metrics: ExecutionMetrics }> {
  const startTime = Date.now();
  let sumToolTimeMs = 0;

  const timedExecutor: ToolExecutor = async (tool) => {
    const toolStart = Date.now();
    const result = await executor(tool);
    sumToolTimeMs += Date.now() - toolStart;
    return result;
  };

  const { parallel, sequential } = classifyToolDependencies(toolCalls, config);
  const results = await executeToolCalls(toolCalls, timedExecutor, config);

  const wallTimeMs = Date.now() - startTime;
  const parallelBatches = Math.ceil(parallel.length / config.maxConcurrentTools);

  const metrics: ExecutionMetrics = {
    totalTools: toolCalls.length,
    parallelBatches,
    sequentialTools: sequential.length,
    wallTimeMs,
    sumToolTimeMs,
    speedup: sumToolTimeMs > 0 ? sumToolTimeMs / wallTimeMs : 1,
  };

  return { results, metrics };
}

/**
 * Automatic Retry with Alternative Approaches
 * 
 * When a tool fails, diagnoses the error and attempts recovery
 * using alternative strategies before giving up.
 */

import type { ToolCall, ToolResult, LLMCaller } from "../types.js";

// ============================================================================
// Types
// ============================================================================

export interface RetryConfig {
  /** Enable automatic retries */
  enabled: boolean;
  /** Maximum retry attempts per tool call */
  maxAttempts: number;
  /** Delay between retries (ms) */
  retryDelayMs: number;
  /** Use LLM to generate alternative approaches */
  useLLMAlternatives: boolean;
  /** Learn from errors across sessions */
  learnFromErrors: boolean;
}

export interface ErrorDiagnosis {
  category: ErrorCategory;
  isRetryable: boolean;
  suggestedFix: string;
  alternativeApproach?: AlternativeApproach;
}

export interface AlternativeApproach {
  description: string;
  modifiedTool?: ToolCall;
  differentTool?: ToolCall;
}

export interface RetryAttempt {
  attemptNumber: number;
  originalTool: ToolCall;
  usedTool: ToolCall;
  result: ToolResult;
  diagnosis?: ErrorDiagnosis;
  timestamp: number;
}

export interface RetryResult {
  success: boolean;
  finalResult: ToolResult;
  attempts: RetryAttempt[];
  totalAttempts: number;
  recoveryStrategy?: string;
}

export type ErrorCategory =
  | "permission"
  | "not_found"
  | "network"
  | "timeout"
  | "rate_limit"
  | "invalid_input"
  | "resource_busy"
  | "quota_exceeded"
  | "syntax_error"
  | "dependency_missing"
  | "unknown";

// ============================================================================
// Error Patterns
// ============================================================================

const ERROR_PATTERNS: Array<{
  pattern: RegExp;
  category: ErrorCategory;
  retryable: boolean;
  fix: string;
}> = [
  // Permission errors
  { pattern: /permission denied|access denied|EACCES|EPERM/i, category: "permission", retryable: false, fix: "Check file permissions or use sudo" },
  { pattern: /unauthorized|401|forbidden|403/i, category: "permission", retryable: false, fix: "Check authentication credentials" },

  // Not found errors
  { pattern: /not found|ENOENT|no such file|does not exist|404/i, category: "not_found", retryable: false, fix: "Verify path exists or create it first" },
  { pattern: /command not found|not recognized/i, category: "not_found", retryable: false, fix: "Install required command or check PATH" },

  // Network errors
  { pattern: /network|ECONNREFUSED|ENOTFOUND|ETIMEDOUT|connection refused/i, category: "network", retryable: true, fix: "Check network connectivity and try again" },
  { pattern: /DNS|resolve|lookup failed/i, category: "network", retryable: true, fix: "Check DNS resolution" },

  // Timeout errors
  { pattern: /timeout|timed out|deadline exceeded/i, category: "timeout", retryable: true, fix: "Increase timeout or simplify operation" },

  // Rate limiting
  { pattern: /rate limit|too many requests|429|throttle/i, category: "rate_limit", retryable: true, fix: "Wait and retry with exponential backoff" },
  { pattern: /quota|limit exceeded|capacity/i, category: "quota_exceeded", retryable: false, fix: "Check quota limits or upgrade plan" },

  // Input errors
  { pattern: /invalid|malformed|bad request|400|syntax error/i, category: "invalid_input", retryable: false, fix: "Check input format and parameters" },
  { pattern: /unexpected token|parse error|JSON/i, category: "syntax_error", retryable: false, fix: "Fix syntax in input data" },

  // Resource errors
  { pattern: /busy|locked|in use|EBUSY/i, category: "resource_busy", retryable: true, fix: "Wait for resource to become available" },
  { pattern: /no space|disk full|ENOSPC/i, category: "quota_exceeded", retryable: false, fix: "Free up disk space" },

  // Dependency errors
  { pattern: /module not found|cannot find|import error|require\(\)/i, category: "dependency_missing", retryable: false, fix: "Install missing dependency" },
];

// ============================================================================
// Alternative Approach Generators
// ============================================================================

const ALTERNATIVE_STRATEGIES: Record<ErrorCategory, (tool: ToolCall, error: string) => AlternativeApproach | null> = {
  permission: (tool) => {
    if (tool.name === "exec" && tool.arguments?.command) {
      const cmd = String(tool.arguments.command);
      // Don't suggest sudo for dangerous commands
      if (!/rm\s+-rf|dd\s+if/i.test(cmd)) {
        return {
          description: "Try with elevated permissions",
          modifiedTool: {
            ...tool,
            arguments: { ...tool.arguments, command: `sudo ${cmd}` },
          },
        };
      }
    }
    return null;
  },

  not_found: (tool) => {
    if (tool.name === "Read") {
      return {
        description: "Check if path exists first",
        differentTool: {
          id: `alt_${Date.now()}`,
          name: "exec",
          arguments: { command: `ls -la "${tool.arguments?.path || ""}"` },
        },
      };
    }
    if (tool.name === "exec" && tool.arguments?.command) {
      const cmd = String(tool.arguments.command);
      // If command not found, try with full path or package manager
      return {
        description: "Install missing command",
        differentTool: {
          id: `alt_${Date.now()}`,
          name: "exec", 
          arguments: { command: `which ${cmd.split(" ")[0]} || apt-get install -y ${cmd.split(" ")[0]} 2>/dev/null || npm install -g ${cmd.split(" ")[0]}` },
        },
      };
    }
    return null;
  },

  network: () => ({
    description: "Retry after brief delay",
    // Same tool, just retry
  }),

  timeout: (tool) => {
    if (tool.name === "exec" && tool.arguments) {
      return {
        description: "Retry with increased timeout",
        modifiedTool: {
          ...tool,
          arguments: { ...tool.arguments, timeout: ((tool.arguments.timeout as number) || 30) * 2 },
        },
      };
    }
    return null;
  },

  rate_limit: () => ({
    description: "Wait and retry with backoff",
  }),

  invalid_input: () => null, // Need human intervention

  resource_busy: () => ({
    description: "Wait for resource and retry",
  }),

  quota_exceeded: () => null, // Can't automatically fix

  syntax_error: () => null, // Need to fix syntax

  dependency_missing: (tool) => {
    if (tool.name === "exec") {
      return {
        description: "Install missing dependency first",
        // Would need context to know what to install
      };
    }
    return null;
  },

  unknown: () => null,
};

// ============================================================================
// Retry Engine
// ============================================================================

const DEFAULT_CONFIG: RetryConfig = {
  enabled: true,
  maxAttempts: 3,
  retryDelayMs: 1000,
  useLLMAlternatives: false,
  learnFromErrors: true,
};

export class RetryEngine {
  private config: RetryConfig;
  private llmCaller?: LLMCaller;
  private errorHistory: Array<{ tool: string; error: string; solution: string }> = [];

  constructor(config: Partial<RetryConfig> = {}, llmCaller?: LLMCaller) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.llmCaller = llmCaller;
  }

  /**
   * Diagnose an error and suggest recovery
   */
  diagnose(tool: ToolCall, error: string): ErrorDiagnosis {
    // Match against known patterns
    for (const { pattern, category, retryable, fix } of ERROR_PATTERNS) {
      if (pattern.test(error)) {
        const altGenerator = ALTERNATIVE_STRATEGIES[category];
        const alternative = altGenerator?.(tool, error) ?? undefined;

        return {
          category,
          isRetryable: retryable,
          suggestedFix: fix,
          alternativeApproach: alternative,
        };
      }
    }

    // Check error history for learned solutions
    const historicalMatch = this.errorHistory.find(h => 
      h.tool === tool.name && error.includes(h.error.slice(0, 50))
    );

    if (historicalMatch) {
      return {
        category: "unknown",
        isRetryable: true,
        suggestedFix: `Previously resolved: ${historicalMatch.solution}`,
      };
    }

    return {
      category: "unknown",
      isRetryable: false,
      suggestedFix: "Unknown error - may require manual intervention",
    };
  }

  /**
   * Execute a tool with automatic retry
   */
  async executeWithRetry(
    tool: ToolCall,
    executor: (t: ToolCall) => Promise<ToolResult>
  ): Promise<RetryResult> {
    const attempts: RetryAttempt[] = [];
    let currentTool = tool;
    let attempt = 0;

    while (attempt < this.config.maxAttempts) {
      attempt++;

      const result = await executor(currentTool);

      const attemptRecord: RetryAttempt = {
        attemptNumber: attempt,
        originalTool: tool,
        usedTool: currentTool,
        result,
        timestamp: Date.now(),
      };

      if (result.success) {
        attempts.push(attemptRecord);

        // Learn from successful retry
        if (attempt > 1 && this.config.learnFromErrors) {
          this.recordSuccess(tool, currentTool, attempts[0].result.error || "");
        }

        return {
          success: true,
          finalResult: result,
          attempts,
          totalAttempts: attempt,
          recoveryStrategy: attempt > 1 ? "retry_succeeded" : undefined,
        };
      }

      // Diagnose the error
      const diagnosis = this.diagnose(currentTool, result.error || "Unknown error");
      attemptRecord.diagnosis = diagnosis;
      attempts.push(attemptRecord);

      // If not retryable or last attempt, give up
      if (!diagnosis.isRetryable || attempt >= this.config.maxAttempts) {
        return {
          success: false,
          finalResult: result,
          attempts,
          totalAttempts: attempt,
        };
      }

      // Try alternative approach if available
      if (diagnosis.alternativeApproach?.modifiedTool) {
        currentTool = diagnosis.alternativeApproach.modifiedTool;
      } else if (diagnosis.alternativeApproach?.differentTool) {
        // For different tool, we'd need to handle separately
        // For now, just retry same tool
      }

      // Wait before retry
      await this.delay(this.config.retryDelayMs * attempt); // Exponential-ish backoff
    }

    return {
      success: false,
      finalResult: attempts[attempts.length - 1]?.result ?? { success: false, error: "Max attempts reached" },
      attempts,
      totalAttempts: attempt,
    };
  }

  /**
   * Generate LLM-powered alternative approach
   */
  async generateAlternative(
    tool: ToolCall,
    error: string,
    previousAttempts: RetryAttempt[]
  ): Promise<AlternativeApproach | null> {
    if (!this.llmCaller || !this.config.useLLMAlternatives) {
      return null;
    }

    const prompt = `A tool call failed. Suggest an alternative approach.

Tool: ${tool.name}
Arguments: ${JSON.stringify(tool.arguments)}
Error: ${error}

Previous attempts: ${previousAttempts.length}

Suggest either:
1. Modified arguments for the same tool
2. A different tool to achieve the same goal
3. Preparatory steps needed first

Answer in JSON:
{
  "description": "What to try",
  "approach": "modify_args" | "different_tool" | "prep_step",
  "tool": "tool_name",
  "arguments": { ... }
}`;

    try {
      const response = await this.llmCaller({
        messages: [
          { role: "system", content: "You help fix failed tool calls. Output valid JSON only." },
          { role: "user", content: prompt },
        ],
        maxTokens: 300,
      });

      const parsed = JSON.parse(response.content);

      if (parsed.approach === "modify_args") {
        return {
          description: parsed.description,
          modifiedTool: { id: tool.id, name: tool.name, arguments: parsed.arguments },
        };
      } else if (parsed.approach === "different_tool") {
        return {
          description: parsed.description,
          differentTool: { id: `alt_${Date.now()}`, name: parsed.tool, arguments: parsed.arguments },
        };
      }

      return { description: parsed.description };
    } catch {
      return null;
    }
  }

  /**
   * Record a successful recovery for future learning
   */
  private recordSuccess(originalTool: ToolCall, successfulTool: ToolCall, error: string): void {
    const solution = originalTool === successfulTool 
      ? "Retry succeeded"
      : `Modified: ${JSON.stringify(successfulTool.arguments)}`;

    this.errorHistory.push({
      tool: originalTool.name,
      error: error.slice(0, 100),
      solution,
    });

    // Keep history bounded
    if (this.errorHistory.length > 100) {
      this.errorHistory = this.errorHistory.slice(-50);
    }
  }

  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

