/**
 * Planning and Reflection
 * 
 * Generates execution plans and assesses progress after actions.
 */

import type {
  TaskPlan,
  PlanStep,
  ReflectionResult,
  LLMCaller,
  ToolCall,
  ToolResult,
  PlanningConfig,
} from "../types.js";

// ============================================================================
// Plan Generation
// ============================================================================

const PLAN_GENERATION_PROMPT = `Given the user's goal, create a structured execution plan.

Goal: {goal}

Create a plan with:
1. Clear subtasks (2-7 steps, max {maxSteps})
2. Dependencies between steps (which steps must complete before others)
3. Success criteria for each step
4. Estimated complexity (low/medium/high)

Format your response as JSON:
{
  "steps": [
    {
      "id": "step_1",
      "title": "Step title",
      "action": "What to do",
      "dependencies": [],
      "successCriteria": "How to know it's done",
      "complexity": "low|medium|high"
    }
  ],
  "assumptions": ["Any assumptions made"],
  "notes": "Optional notes about the plan"
}

Be concise. Only include steps that require tool use or significant work.`;

/**
 * Check if planning is needed for this goal.
 * Creates a new plan if: no plan exists, existing plan is completed/stale,
 * or the user's goal has pivoted away from the existing plan.
 */
export function shouldGeneratePlan(
  goal: string,
  existingPlan: TaskPlan | null,
  config: PlanningConfig
): boolean {
  if (!config.enabled) return false;

  // If there's an active plan, check if the goal has pivoted.
  // A pivot = the new goal is substantially different from the existing plan's goal.
  if (existingPlan && existingPlan.status === "active") {
    if (!isGoalPivot(goal, existingPlan.goal)) {
      return false; // Same goal direction, keep existing plan
    }
    // Goal pivoted -- fall through to intent/complexity checks below
    // to decide if the new goal warrants a plan
  }

  const lowerGoal = goal.toLowerCase();

  // ═══════════════════════════════════════════════════════════════════════════
  // INTENT DETECTION - Explicit planning requests trigger immediately
  // ═══════════════════════════════════════════════════════════════════════════

  // Direct planning verbs (user explicitly wants a plan)
  const explicitPlanningPatterns = [
    /\bplan\b/i,                          // "plan a website", "help me plan"
    /\bplanning\b/i,                      // "I need help planning"
    /\bfigure out\b/i,                    // "figure out how to..."
    /\bhelp me\b/i,                       // "help me build...", "help me create..."
    /\bwhat('s| is) the best way\b/i,     // "what's the best way to..."
    /\bhow (should|do|can|would) (i|we)\b/i, // "how should I...", "how do I..."
    /\bwhat steps\b/i,                    // "what steps do I need..."
    /\bwalk me through\b/i,               // "walk me through..."
    /\bguide me\b/i,                      // "guide me through..."
    /\bbreak (it |this )?down\b/i,        // "break it down", "break this down"
    /\bstep.by.step\b/i,                  // "do this step by step"
    /\boutline\b/i,                       // "outline the process"
    /\bstrategy for\b/i,                  // "strategy for building..."
    /\bapproach to\b/i,                   // "best approach to..."
    /\bi need to\b/i,                     // "I need to build..."
    /\bi want to\b/i,                     // "I want to create..."
  ];

  if (explicitPlanningPatterns.some(p => p.test(goal))) {
    return true;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // TASK COMPLEXITY - Multi-step tasks that benefit from planning
  // ═══════════════════════════════════════════════════════════════════════════

  // Complex action verbs (tasks that typically require multiple steps)
  const complexVerbs = /\b(build|create|develop|implement|design|setup|set up|configure|deploy|migrate|refactor|integrate|automate|architect|establish|construct|launch|ship)\b/i;

  // Sequential/multi-part indicators
  const sequentialIndicators = [
    goal.includes(" and "),               // "X and Y"
    goal.includes(" then "),              // "X then Y"
    goal.includes(", then"),              // "X, then Y"
    /\bfirst\b.*\bthen\b/i.test(goal),    // "first... then..."
    /\bafter\b.*\b(do|create|make)\b/i.test(goal), // "after X, do Y"
  ];

  // Task nouns that typically require multi-step work
  const complexTaskNouns = /\b(api|website|site|app|application|service|system|database|server|pipeline|workflow|bot|agent|project|dashboard|interface|platform|infrastructure)\b/i;

  // Complexity indicators
  const complexityIndicators = [
    goal.length > 100,                                    // Long request
    goal.split(/[.!?]/).filter(Boolean).length > 2,       // Multiple sentences  
    complexVerbs.test(goal) && complexTaskNouns.test(goal), // Complex verb + task noun
    /\bfull\b|\bcomplete\b|\bentire\b|\bwhole\b/i.test(goal), // Scope words
    /\bproduction\b|\bprod\b/i.test(goal),                // Production deployment
    /\bfrom scratch\b/i.test(goal),                       // Starting fresh
    /\bend.to.end\b|\be2e\b/i.test(goal),                 // End-to-end
    /\bnew\b/i.test(goal) && complexVerbs.test(goal),     // "new" + complex verb
  ];

  // Count indicators
  const sequentialScore = sequentialIndicators.filter(Boolean).length;
  const complexityScore = complexityIndicators.filter(Boolean).length;

  // Plan if: any sequential indicator OR 1+ complexity indicators
  return sequentialScore >= 1 || complexityScore >= 1;
}

/**
 * Generate an execution plan
 */
export async function generatePlan(
  goal: string,
  context: string,
  config: PlanningConfig,
  llmCall: LLMCaller
): Promise<TaskPlan> {
  const prompt = PLAN_GENERATION_PROMPT
    .replace("{goal}", goal)
    .replace("{maxSteps}", String(config.maxPlanSteps));

  const response = await llmCall({
    messages: [
      { role: "system", content: "You are a planning assistant. Output valid JSON only." },
      { role: "user", content: `${prompt}\n\nContext:\n${context}` },
    ],
    maxTokens: 1500,
  });

  // Parse the response
  const parsed = parseJsonFromResponse(response.content);

  if (!parsed || !Array.isArray(parsed.steps)) {
    // Fallback: single-step plan
    return {
      id: generatePlanId(),
      goal,
      steps: [{
        id: "step_1",
        title: "Execute request",
        action: goal,
        dependencies: [],
        successCriteria: "Request completed successfully",
        complexity: "medium",
        status: "pending",
      }],
      assumptions: [],
      createdAt: Date.now(),
      status: "active",
    };
  }

  const steps: PlanStep[] = parsed.steps.map((s: Record<string, unknown>, i: number) => ({
    id: (s.id as string) || `step_${i + 1}`,
    title: (s.title as string) || `Step ${i + 1}`,
    action: (s.action as string) || "",
    dependencies: (s.dependencies as string[]) || [],
    successCriteria: (s.successCriteria as string) || "",
    complexity: (s.complexity as "low" | "medium" | "high") || "medium",
    status: "pending" as const,
  }));

  return {
    id: generatePlanId(),
    goal,
    steps,
    assumptions: (parsed.assumptions as string[]) || [],
    createdAt: Date.now(),
    status: "active",
  };
}

// ============================================================================
// Reflection
// ============================================================================

const REFLECTION_PROMPT = `Given your plan and the last action result, assess progress.

Plan: {plan}

Last action: {action}
Result: {result}

Answer concisely in JSON:
{
  "actionSucceeded": true|false|"partial",
  "onTrack": true|false,
  "decision": "continue"|"replan"|"escalate",
  "reason": "Brief explanation if decision is not 'continue'"
}`;

/**
 * Reflect on progress after a tool execution
 */
export async function reflect(
  plan: TaskPlan,
  lastAction: ToolCall,
  result: ToolResult,
  config: PlanningConfig,
  llmCall: LLMCaller
): Promise<ReflectionResult> {
  if (!config.reflectionAfterTools) {
    // Skip reflection, assume success
    return {
      actionSucceeded: result.success,
      onTrack: result.success,
      decision: result.success ? "continue" : "replan",
    };
  }

  const planSummary = plan.steps
    .map((s, i) => `${i + 1}. [${s.status}] ${s.title}`)
    .join("\n");

  const prompt = REFLECTION_PROMPT
    .replace("{plan}", planSummary)
    .replace("{action}", `${lastAction.name}(${JSON.stringify(lastAction.arguments)})`)
    .replace("{result}", result.error || JSON.stringify(result.output ?? "success"));

  try {
    const response = await llmCall({
      messages: [
        { role: "system", content: "You are assessing progress. Output valid JSON only." },
        { role: "user", content: prompt },
      ],
      maxTokens: 300,
    });

    const parsed = parseJsonFromResponse(response.content);

    if (!parsed) {
      return {
        actionSucceeded: result.success,
        onTrack: result.success,
        decision: result.success ? "continue" : "replan",
      };
    }

    return {
      actionSucceeded: (parsed.actionSucceeded as boolean | "partial") ?? result.success,
      onTrack: (parsed.onTrack as boolean) ?? result.success,
      decision: (parsed.decision as "continue" | "replan" | "escalate") ?? "continue",
      reason: parsed.reason as string | undefined,
    };
  } catch {
    // Reflection failed, continue anyway
    return {
      actionSucceeded: result.success,
      onTrack: result.success,
      decision: result.success ? "continue" : "replan",
    };
  }
}

// ============================================================================
// Replanning
// ============================================================================

const REPLAN_PROMPT = `The current plan needs adjustment.

Original plan:
{originalPlan}

Reason for replanning: {reason}

Current status:
- Completed: {completed}
- Remaining: {remaining}

Create a revised plan that addresses the issue. Keep completed steps, adjust remaining ones.

Output valid JSON with the same format as the original plan.`;

/**
 * Revise the plan based on reflection
 */
export async function replan(
  plan: TaskPlan,
  reason: string,
  config: PlanningConfig,
  llmCall: LLMCaller
): Promise<TaskPlan> {
  const completed = plan.steps
    .filter((s) => s.status === "complete")
    .map((s) => s.title)
    .join(", ") || "none";

  const remaining = plan.steps
    .filter((s) => s.status !== "complete")
    .map((s) => s.title)
    .join(", ") || "none";

  const originalPlan = plan.steps
    .map((s, i) => `${i + 1}. [${s.status}] ${s.title}: ${s.action}`)
    .join("\n");

  const prompt = REPLAN_PROMPT
    .replace("{originalPlan}", originalPlan)
    .replace("{reason}", reason)
    .replace("{completed}", completed)
    .replace("{remaining}", remaining);

  try {
    const response = await llmCall({
      messages: [
        { role: "system", content: "You are revising a plan. Output valid JSON only." },
        { role: "user", content: prompt },
      ],
      maxTokens: 1500,
    });

    const parsed = parseJsonFromResponse(response.content);

    if (!parsed || !Array.isArray(parsed.steps)) {
      // Keep existing plan
      return plan;
    }

    // Preserve completed steps, merge new steps
    const completedSteps = plan.steps.filter((s) => s.status === "complete");
    const newSteps: PlanStep[] = parsed.steps.map((s: Record<string, unknown>, i: number) => ({
      id: (s.id as string) || `step_${completedSteps.length + i + 1}`,
      title: (s.title as string) || `Step ${i + 1}`,
      action: (s.action as string) || "",
      dependencies: (s.dependencies as string[]) || [],
      successCriteria: (s.successCriteria as string) || "",
      complexity: (s.complexity as "low" | "medium" | "high") || "medium",
      status: "pending" as const,
    }));

    return {
      ...plan,
      steps: [...completedSteps, ...newSteps],
      createdAt: Date.now(), // Update timestamp
    };
  } catch {
    // Replanning failed, keep existing
    return plan;
  }
}

// ============================================================================
// Plan Updates
// ============================================================================

/**
 * Mark a plan step as complete
 */
export function completeStep(plan: TaskPlan, stepId: string, result?: string): TaskPlan {
  const steps = plan.steps.map((s) =>
    s.id === stepId ? { ...s, status: "complete" as const, result } : s
  );

  // Check if all steps complete
  const allComplete = steps.every((s) => s.status === "complete");

  return {
    ...plan,
    steps,
    status: allComplete ? "completed" : plan.status,
  };
}

/**
 * Mark a plan step as failed
 */
export function failStep(plan: TaskPlan, stepId: string, error: string): TaskPlan {
  const steps = plan.steps.map((s) =>
    s.id === stepId ? { ...s, status: "failed" as const, result: error } : s
  );

  return {
    ...plan,
    steps,
  };
}

/**
 * Get the next pending step
 */
export function getNextStep(plan: TaskPlan): PlanStep | null {
  // Find first pending step with no pending dependencies
  for (const step of plan.steps) {
    if (step.status !== "pending") continue;

    const depsComplete = step.dependencies.every((depId) => {
      const dep = plan.steps.find((s) => s.id === depId);
      return dep?.status === "complete";
    });

    if (depsComplete) return step;
  }

  return null;
}

/**
 * Format plan for context injection
 */
export function formatPlanForContext(plan: TaskPlan): string {
  const lines = [
    "## Execution Plan",
    "",
    `**Goal:** ${plan.goal}`,
    "",
    "### Steps",
  ];

  for (const step of plan.steps) {
    const status = step.status === "complete" ? "✓" :
                   step.status === "in_progress" ? "◐" :
                   step.status === "failed" ? "✗" : "○";
    lines.push(`${status} **${step.title}**`);
    lines.push(`  - Action: ${step.action}`);
    lines.push(`  - Success: ${step.successCriteria}`);
    if (step.result) {
      lines.push(`  - Result: ${step.result}`);
    }
  }

  if (plan.assumptions.length > 0) {
    lines.push("");
    lines.push("### Assumptions");
    for (const assumption of plan.assumptions) {
      lines.push(`- ${assumption}`);
    }
  }

  return lines.join("\n");
}

// ============================================================================
// Goal Pivot Detection
// ============================================================================

/**
 * Detect if the user's new goal has pivoted away from the existing plan's goal.
 * Uses keyword overlap: if fewer than 20% of significant words overlap,
 * the goal has likely changed. Short/conversational messages (< 20 chars)
 * are not treated as pivots to avoid replanning on follow-ups like "ok" or "yes".
 */
function isGoalPivot(newGoal: string, existingGoal: string): boolean {
  // Short follow-ups (e.g. "yes", "ok", "continue", "go ahead") aren't pivots
  if (newGoal.trim().length < 20) return false;

  const stopWords = new Set([
    "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
    "have", "has", "had", "do", "does", "did", "will", "would", "shall",
    "should", "may", "might", "must", "can", "could", "to", "of", "in",
    "for", "on", "with", "at", "by", "from", "as", "into", "through",
    "during", "before", "after", "above", "below", "between", "out",
    "off", "over", "under", "again", "further", "then", "once", "here",
    "there", "when", "where", "why", "how", "all", "both", "each",
    "few", "more", "most", "other", "some", "such", "no", "nor", "not",
    "only", "own", "same", "so", "than", "too", "very", "just", "about",
    "it", "its", "i", "me", "my", "we", "our", "you", "your", "he",
    "she", "they", "them", "this", "that", "these", "those", "and", "but",
    "or", "if", "while", "because", "until", "although", "also", "please",
    "help", "need", "want", "let", "make", "get",
  ]);

  const extractKeywords = (text: string): Set<string> => {
    const words = text.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/);
    return new Set(words.filter((w) => w.length > 2 && !stopWords.has(w)));
  };

  const newKeywords = extractKeywords(newGoal);
  const existingKeywords = extractKeywords(existingGoal);

  if (newKeywords.size === 0 || existingKeywords.size === 0) return false;

  // Count overlap
  let overlap = 0;
  for (const word of newKeywords) {
    if (existingKeywords.has(word)) overlap++;
  }

  // If < 20% of the new goal's keywords appear in the existing plan, it's a pivot
  const overlapRatio = overlap / newKeywords.size;
  return overlapRatio < 0.2;
}

// ============================================================================
// Utilities
// ============================================================================

function generatePlanId(): string {
  return `plan_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
}

function parseJsonFromResponse(content: string): Record<string, unknown> | null {
  try {
    // Try direct parse first
    return JSON.parse(content);
  } catch {
    // Try to extract JSON from markdown code block
    const match = content.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (match) {
      try {
        return JSON.parse(match[1]);
      } catch {
        return null;
      }
    }
    return null;
  }
}

/**
 * Checkpoint/Restore System
 * 
 * Enables saving and restoring agent state for long-running tasks.
 * Supports automatic checkpointing at intervals and on significant events.
 */

import fs from "node:fs/promises";
import fsSync from "node:fs";
import path from "node:path";
import type { TaskPlan } from "../types.js";
import type { PlanState } from "./persistence.js";
import type { Message } from "../context/summarizer.js";

// ============================================================================
// Types
// ============================================================================

export interface CheckpointData {
  id: string;
  version: number;
  timestamp: number;
  sessionId: string;

  // Plan state
  plan: TaskPlan | null;
  activeStepId: string | null;
  completedStepIds: string[];
  failedStepIds: string[];

  // Execution context
  context: {
    turnCount: number;
    totalToolCalls: number;
    totalErrors: number;
    lastActivity: number;
    startedAt: number;
  };

  // Conversation state
  recentMessages?: Message[];
  conversationSummary?: string;

  // Task metadata
  metadata: {
    description?: string;
    trigger?: "manual" | "auto" | "interval" | "error";
    stepAtCheckpoint?: string;
  };
}

export interface CheckpointConfig {
  /** Enable checkpointing */
  enabled: boolean;
  /** Directory for checkpoint files */
  checkpointDir: string;
  /** Auto-checkpoint interval (ms), 0 to disable */
  autoCheckpointInterval: number;
  /** Max checkpoints to keep per session */
  maxCheckpointsPerSession: number;
  /** Checkpoint on step completion */
  checkpointOnStepComplete: boolean;
  /** Checkpoint on errors */
  checkpointOnError: boolean;
}

export interface RestoreResult {
  success: boolean;
  checkpoint?: CheckpointData;
  error?: string;
  resumePrompt?: string;
}

// ============================================================================
// Checkpoint Manager
// ============================================================================

const DEFAULT_CONFIG: CheckpointConfig = {
  enabled: true,
  checkpointDir: "",  // Set in constructor
  autoCheckpointInterval: 60000, // 1 minute
  maxCheckpointsPerSession: 5,
  checkpointOnStepComplete: true,
  checkpointOnError: true,
};

const CHECKPOINT_VERSION = 1;

export class CheckpointManager {
  private config: CheckpointConfig;
  private autoCheckpointTimer: NodeJS.Timeout | null = null;
  private lastCheckpoint: CheckpointData | null = null;

  constructor(config: Partial<CheckpointConfig> = {}) {
    const home = process.env.HOME || process.env.USERPROFILE || "/tmp";
    this.config = { 
      ...DEFAULT_CONFIG, 
      checkpointDir: path.join(home, ".openclaw", "checkpoints"),
      ...config,
    };
  }

  /**
   * Create a checkpoint from current state
   */
  async createCheckpoint(
    state: PlanState,
    options: {
      description?: string;
      trigger?: CheckpointData["metadata"]["trigger"];
      recentMessages?: Message[];
      conversationSummary?: string;
    } = {}
  ): Promise<CheckpointData> {
    const checkpoint: CheckpointData = {
      id: this.generateCheckpointId(),
      version: CHECKPOINT_VERSION,
      timestamp: Date.now(),
      sessionId: state.sessionId,

      plan: state.plan,
      activeStepId: state.activeStepId,
      completedStepIds: [...state.completedStepIds],
      failedStepIds: [...state.failedStepIds],

      context: { ...state.context },

      recentMessages: options.recentMessages,
      conversationSummary: options.conversationSummary,

      metadata: {
        description: options.description,
        trigger: options.trigger ?? "manual",
        stepAtCheckpoint: state.activeStepId ?? undefined,
      },
    };

    await this.saveCheckpoint(checkpoint);
    this.lastCheckpoint = checkpoint;

    // Cleanup old checkpoints
    await this.cleanupOldCheckpoints(state.sessionId);

    return checkpoint;
  }

  /**
   * Restore from a checkpoint
   */
  async restore(
    sessionId: string,
    checkpointId?: string
  ): Promise<RestoreResult> {
    try {
      // Find checkpoint
      let checkpoint: CheckpointData | null = null;

      if (checkpointId) {
        checkpoint = await this.loadCheckpoint(sessionId, checkpointId);
      } else {
        // Get most recent
        checkpoint = await this.getLatestCheckpoint(sessionId);
      }

      if (!checkpoint) {
        return {
          success: false,
          error: "No checkpoint found",
        };
      }

      // Generate resume prompt
      const resumePrompt = this.generateResumePrompt(checkpoint);

      return {
        success: true,
        checkpoint,
        resumePrompt,
      };
    } catch (err) {
      return {
        success: false,
        error: `Failed to restore: ${err}`,
      };
    }
  }

  /**
   * List available checkpoints for a session
   */
  async listCheckpoints(sessionId: string): Promise<CheckpointData[]> {
    const sessionDir = this.getSessionDir(sessionId);

    try {
      const files = await fs.readdir(sessionDir);
      const checkpoints: CheckpointData[] = [];

      for (const file of files) {
        if (!file.endsWith(".json")) continue;
        try {
          const content = await fs.readFile(path.join(sessionDir, file), "utf-8");
          checkpoints.push(JSON.parse(content));
        } catch {
          // Skip invalid files
        }
      }

      // Sort by timestamp descending
      return checkpoints.sort((a, b) => b.timestamp - a.timestamp);
    } catch {
      return [];
    }
  }

  /**
   * Get the latest checkpoint for a session
   */
  async getLatestCheckpoint(sessionId: string): Promise<CheckpointData | null> {
    const checkpoints = await this.listCheckpoints(sessionId);
    return checkpoints[0] ?? null;
  }

  /**
   * Check if a session has incomplete work to resume
   */
  async hasIncompleteWork(sessionId: string): Promise<{
    hasWork: boolean;
    checkpoint?: CheckpointData;
    description?: string;
  }> {
    const checkpoint = await this.getLatestCheckpoint(sessionId);

    if (!checkpoint?.plan) {
      return { hasWork: false };
    }

    // Check if plan is incomplete
    const totalSteps = checkpoint.plan.steps.length;
    const completedSteps = checkpoint.completedStepIds.length;
    const isIncomplete = completedSteps < totalSteps && 
                         checkpoint.plan.status !== "completed" &&
                         checkpoint.plan.status !== "abandoned";

    if (!isIncomplete) {
      return { hasWork: false };
    }

    // Calculate time since checkpoint
    const hoursSince = (Date.now() - checkpoint.timestamp) / (1000 * 60 * 60);

    return {
      hasWork: true,
      checkpoint,
      description: `Incomplete task: "${checkpoint.plan.goal}" (${completedSteps}/${totalSteps} steps, paused ${hoursSince.toFixed(1)}h ago)`,
    };
  }

  /**
   * Start auto-checkpointing
   */
  startAutoCheckpoint(
    sessionId: string,
    getState: () => PlanState | null
  ): void {
    if (!this.config.enabled || this.config.autoCheckpointInterval <= 0) return;

    this.stopAutoCheckpoint();

    this.autoCheckpointTimer = setInterval(async () => {
      const state = getState();
      if (state?.plan && state.activeStepId) {
        await this.createCheckpoint(state, {
          trigger: "interval",
          description: "Auto-checkpoint",
        });
      }
    }, this.config.autoCheckpointInterval);
  }

  /**
   * Stop auto-checkpointing
   */
  stopAutoCheckpoint(): void {
    if (this.autoCheckpointTimer) {
      clearInterval(this.autoCheckpointTimer);
      this.autoCheckpointTimer = null;
    }
  }

  /**
   * Delete a checkpoint
   */
  async deleteCheckpoint(sessionId: string, checkpointId: string): Promise<boolean> {
    const filePath = path.join(this.getSessionDir(sessionId), `${checkpointId}.json`);
    try {
      await fs.unlink(filePath);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Format checkpoint for display
   */
  formatCheckpoint(checkpoint: CheckpointData): string {
    const date = new Date(checkpoint.timestamp).toLocaleString();
    const progress = checkpoint.plan 
      ? `${checkpoint.completedStepIds.length}/${checkpoint.plan.steps.length} steps`
      : "No plan";

    return `
📍 **Checkpoint: ${checkpoint.id.slice(-8)}**
- **Created:** ${date}
- **Progress:** ${progress}
- **Trigger:** ${checkpoint.metadata.trigger}
${checkpoint.metadata.description ? `- **Note:** ${checkpoint.metadata.description}` : ""}
${checkpoint.plan ? `- **Goal:** ${checkpoint.plan.goal}` : ""}
`.trim();
  }

  /**
   * Format resume offer for user
   */
  formatResumeOffer(checkpoint: CheckpointData): string {
    const hoursSince = (Date.now() - checkpoint.timestamp) / (1000 * 60 * 60);
    const timeAgo = hoursSince < 1 
      ? `${Math.round(hoursSince * 60)} minutes`
      : `${hoursSince.toFixed(1)} hours`;

    return `
🔄 **Incomplete Task Found**

You have an unfinished task from ${timeAgo} ago:

**Goal:** ${checkpoint.plan?.goal ?? "Unknown"}
**Progress:** ${checkpoint.completedStepIds.length}/${checkpoint.plan?.steps.length ?? 0} steps completed
**Paused at:** ${checkpoint.metadata.stepAtCheckpoint ?? "Unknown step"}

Would you like to:
- **Resume** - Continue from where you left off
- **Start fresh** - Begin a new task (checkpoint will be kept)
- **Discard** - Delete the checkpoint and start fresh

Reply with your choice.
`.trim();
  }

  // ──────────────────────────────────────────────────────────────────────────
  // Private Methods
  // ──────────────────────────────────────────────────────────────────────────

  private generateCheckpointId(): string {
    return `ckpt_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  }

  private getSessionDir(sessionId: string): string {
    const safeId = sessionId.replace(/[^a-zA-Z0-9_-]/g, "_");
    return path.join(this.config.checkpointDir, safeId);
  }

  private async saveCheckpoint(checkpoint: CheckpointData): Promise<void> {
    const sessionDir = this.getSessionDir(checkpoint.sessionId);
    await fs.mkdir(sessionDir, { recursive: true });

    const filePath = path.join(sessionDir, `${checkpoint.id}.json`);
    await fs.writeFile(filePath, JSON.stringify(checkpoint, null, 2));
  }

  private async loadCheckpoint(
    sessionId: string,
    checkpointId: string
  ): Promise<CheckpointData | null> {
    const filePath = path.join(this.getSessionDir(sessionId), `${checkpointId}.json`);

    try {
      const content = await fs.readFile(filePath, "utf-8");
      return JSON.parse(content);
    } catch {
      return null;
    }
  }

  private async cleanupOldCheckpoints(sessionId: string): Promise<void> {
    const checkpoints = await this.listCheckpoints(sessionId);
    const max = this.config.maxCheckpointsPerSession;

    if (checkpoints.length <= max) return;

    // Delete oldest checkpoints beyond limit
    const toDelete = checkpoints.slice(max);
    for (const checkpoint of toDelete) {
      await this.deleteCheckpoint(sessionId, checkpoint.id);
    }
  }

  private generateResumePrompt(checkpoint: CheckpointData): string {
    const lines: string[] = [
      "## Resuming from Checkpoint",
      "",
    ];

    if (checkpoint.conversationSummary) {
      lines.push("### Previous Context");
      lines.push(checkpoint.conversationSummary);
      lines.push("");
    }

    if (checkpoint.plan) {
      lines.push("### Plan Status");
      lines.push(`**Goal:** ${checkpoint.plan.goal}`);
      lines.push("");

      for (const step of checkpoint.plan.steps) {
        const isActive = step.id === checkpoint.activeStepId;
        const icon = checkpoint.completedStepIds.includes(step.id) ? "✅" :
                     checkpoint.failedStepIds.includes(step.id) ? "❌" :
                     isActive ? "👉" : "⬜";

        lines.push(`${icon} ${step.title}${isActive ? " ← resume here" : ""}`);
      }
      lines.push("");
    }

    lines.push("Continue executing the plan from the current step.");

    return lines.join("\n");
  }
}

// ============================================================================
// Factory
// ============================================================================

let defaultManager: CheckpointManager | null = null;

export function getCheckpointManager(config?: Partial<CheckpointConfig>): CheckpointManager {
  if (!defaultManager) {
    defaultManager = new CheckpointManager(config);
  }
  return defaultManager;
}

export function resetCheckpointManager(): void {
  defaultManager?.stopAutoCheckpoint();
  defaultManager = null;
}

/**
 * Persistent Plan State
 * 
 * Stores and retrieves plan state across conversation turns.
 * State is persisted per-session to allow resumption.
 */

import fs from "node:fs/promises";
import fsSync from "node:fs";
import path from "node:path";
import type { TaskPlan, PlanStep } from "../types.js";

// ============================================================================
// Types
// ============================================================================

export interface PlanState {
  sessionId: string;
  plan: TaskPlan | null;
  activeStepId: string | null;
  completedStepIds: string[];
  failedStepIds: string[];
  context: {
    turnCount: number;
    totalToolCalls: number;
    totalErrors: number;
    lastActivity: number;
    startedAt: number;
  };
  checkpoints: Checkpoint[];
  metadata: Record<string, unknown>;
}

export interface Checkpoint {
  id: string;
  timestamp: number;
  stepId: string;
  description: string;
  state: Partial<PlanState>;
}

export interface StateManagerConfig {
  stateDir: string;
  autoSaveInterval?: number; // ms, 0 to disable
  maxCheckpoints?: number;
}

// ============================================================================
// State Manager
// ============================================================================

export class PlanStateManager {
  private config: StateManagerConfig;
  private state: PlanState | null = null;
  private dirty: boolean = false;
  private autoSaveTimer: NodeJS.Timeout | null = null;

  constructor(config: StateManagerConfig) {
    this.config = {
      autoSaveInterval: 5000,
      maxCheckpoints: 10,
      ...config,
    };
  }

  /**
   * Initialize or load state for a session
   */
  async init(sessionId: string): Promise<PlanState> {
    const existing = await this.load(sessionId);

    if (existing) {
      this.state = existing;
      this.state.context.turnCount++;
      this.state.context.lastActivity = Date.now();
    } else {
      this.state = this.createEmpty(sessionId);
    }

    this.dirty = true;
    this.startAutoSave();

    return this.state;
  }

  /**
   * Get current state (throws if not initialized)
   */
  get(): PlanState {
    if (!this.state) {
      throw new Error("State not initialized. Call init() first.");
    }
    return this.state;
  }

  /**
   * Get state if available, null otherwise
   */
  getOrNull(): PlanState | null {
    return this.state;
  }

  /**
   * Set the active plan
   */
  setPlan(plan: TaskPlan): void {
    if (!this.state) throw new Error("State not initialized");

    this.state.plan = plan;
    this.state.activeStepId = plan.steps[0]?.id ?? null;
    this.state.completedStepIds = [];
    this.state.failedStepIds = [];
    this.dirty = true;
  }

  /**
   * Mark a step as complete
   */
  completeStep(stepId: string, result?: string): void {
    if (!this.state?.plan) return;

    // Update step status
    const step = this.state.plan.steps.find(s => s.id === stepId);
    if (step) {
      step.status = "complete";
      if (result) step.result = result;
    }

    // Track completion
    if (!this.state.completedStepIds.includes(stepId)) {
      this.state.completedStepIds.push(stepId);
    }

    // Advance to next step
    this.advanceToNextStep();
    this.dirty = true;
  }

  /**
   * Mark a step as failed
   */
  failStep(stepId: string, error: string): void {
    if (!this.state?.plan) return;

    const step = this.state.plan.steps.find(s => s.id === stepId);
    if (step) {
      step.status = "failed";
      step.result = error;
    }

    if (!this.state.failedStepIds.includes(stepId)) {
      this.state.failedStepIds.push(stepId);
    }

    this.state.context.totalErrors++;
    this.dirty = true;
  }

  /**
   * Record a tool call
   */
  recordToolCall(): void {
    if (!this.state) return;
    this.state.context.totalToolCalls++;
    this.state.context.lastActivity = Date.now();
    this.dirty = true;
  }

  /**
   * Get the current active step
   */
  getActiveStep(): PlanStep | null {
    if (!this.state?.plan || !this.state.activeStepId) return null;
    return this.state.plan.steps.find(s => s.id === this.state!.activeStepId) ?? null;
  }

  /**
   * Get plan progress
   */
  getProgress(): { completed: number; total: number; percent: number } {
    if (!this.state?.plan) {
      return { completed: 0, total: 0, percent: 0 };
    }
    const total = this.state.plan.steps.length;
    const completed = this.state.completedStepIds.length;
    return {
      completed,
      total,
      percent: total > 0 ? Math.round((completed / total) * 100) : 0,
    };
  }

  /**
   * Create a checkpoint
   */
  createCheckpoint(description: string): Checkpoint {
    if (!this.state) throw new Error("State not initialized");

    const checkpoint: Checkpoint = {
      id: `ckpt_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
      timestamp: Date.now(),
      stepId: this.state.activeStepId ?? "none",
      description,
      state: {
        plan: this.state.plan ? { ...this.state.plan } : null,
        activeStepId: this.state.activeStepId,
        completedStepIds: [...this.state.completedStepIds],
        context: { ...this.state.context },
      },
    };

    this.state.checkpoints.push(checkpoint);

    // Trim old checkpoints
    const max = this.config.maxCheckpoints ?? 10;
    if (this.state.checkpoints.length > max) {
      this.state.checkpoints = this.state.checkpoints.slice(-max);
    }

    this.dirty = true;
    return checkpoint;
  }

  /**
   * Restore from a checkpoint
   */
  restoreCheckpoint(checkpointId: string): boolean {
    if (!this.state) return false;

    const checkpoint = this.state.checkpoints.find(c => c.id === checkpointId);
    if (!checkpoint?.state) return false;

    // Restore state from checkpoint
    if (checkpoint.state.plan) {
      this.state.plan = checkpoint.state.plan as TaskPlan;
    }
    if (checkpoint.state.activeStepId !== undefined) {
      this.state.activeStepId = checkpoint.state.activeStepId;
    }
    if (checkpoint.state.completedStepIds) {
      this.state.completedStepIds = checkpoint.state.completedStepIds;
    }
    if (checkpoint.state.context) {
      this.state.context = { ...this.state.context, ...checkpoint.state.context };
    }

    this.dirty = true;
    return true;
  }

  /**
   * Format plan state for context injection
   */
  formatForContext(): string {
    if (!this.state?.plan) return "";

    const progress = this.getProgress();
    const lines: string[] = [
      "## Current Plan State",
      "",
      `**Goal:** ${this.state.plan.goal}`,
      `**Progress:** ${progress.completed}/${progress.total} steps (${progress.percent}%)`,
      "",
      "### Steps",
    ];

    for (const step of this.state.plan.steps) {
      const isActive = step.id === this.state.activeStepId;
      const icon = step.status === "complete" ? "✅" :
                   step.status === "failed" ? "❌" :
                   step.status === "in_progress" ? "🔄" :
                   isActive ? "👉" : "⬜";

      lines.push(`${icon} **${step.title}**${isActive ? " ← current" : ""}`);

      if (step.result && step.status !== "pending") {
        lines.push(`   _${step.result}_`);
      }
    }

    if (this.state.checkpoints.length > 0) {
      const latest = this.state.checkpoints[this.state.checkpoints.length - 1];
      lines.push("");
      lines.push(`_Last checkpoint: ${latest.description} (${new Date(latest.timestamp).toLocaleTimeString()})_`);
    }

    return lines.join("\n");
  }

  /**
   * Save state to disk
   */
  async save(): Promise<void> {
    if (!this.state || !this.dirty) return;

    await fs.mkdir(this.config.stateDir, { recursive: true });
    const filePath = this.getStatePath(this.state.sessionId);

    await fs.writeFile(filePath, JSON.stringify(this.state, null, 2));
    this.dirty = false;
  }

  /**
   * Load state from disk
   */
  async load(sessionId: string): Promise<PlanState | null> {
    const filePath = this.getStatePath(sessionId);

    try {
      const content = await fs.readFile(filePath, "utf-8");
      return JSON.parse(content) as PlanState;
    } catch {
      return null;
    }
  }

  /**
   * Check if state exists for session
   */
  hasState(sessionId: string): boolean {
    return fsSync.existsSync(this.getStatePath(sessionId));
  }

  /**
   * Clear state for session
   */
  async clear(sessionId?: string): Promise<void> {
    const id = sessionId ?? this.state?.sessionId;
    if (!id) return;

    const filePath = this.getStatePath(id);
    try {
      await fs.unlink(filePath);
    } catch {
      // Ignore if doesn't exist
    }

    if (this.state?.sessionId === id) {
      this.state = null;
      this.dirty = false;
    }
  }

  /**
   * Cleanup: stop auto-save and save final state
   */
  async cleanup(): Promise<void> {
    this.stopAutoSave();
    await this.save();
  }

  // ──────────────────────────────────────────────────────────────────────────
  // Private Methods
  // ──────────────────────────────────────────────────────────────────────────

  private createEmpty(sessionId: string): PlanState {
    return {
      sessionId,
      plan: null,
      activeStepId: null,
      completedStepIds: [],
      failedStepIds: [],
      context: {
        turnCount: 1,
        totalToolCalls: 0,
        totalErrors: 0,
        lastActivity: Date.now(),
        startedAt: Date.now(),
      },
      checkpoints: [],
      metadata: {},
    };
  }

  private getStatePath(sessionId: string): string {
    // Sanitize session ID for filesystem
    const safeId = sessionId.replace(/[^a-zA-Z0-9_-]/g, "_");
    return path.join(this.config.stateDir, `${safeId}.json`);
  }

  private advanceToNextStep(): void {
    if (!this.state?.plan) return;

    // Find next pending step with satisfied dependencies
    for (const step of this.state.plan.steps) {
      if (step.status !== "pending") continue;

      const depsComplete = step.dependencies.every(depId =>
        this.state!.completedStepIds.includes(depId)
      );

      if (depsComplete) {
        this.state.activeStepId = step.id;
        step.status = "in_progress";
        return;
      }
    }

    // No more steps - plan complete
    this.state.activeStepId = null;
    if (this.state.plan) {
      this.state.plan.status = "completed";
    }
  }

  private startAutoSave(): void {
    if (this.config.autoSaveInterval && this.config.autoSaveInterval > 0) {
      this.autoSaveTimer = setInterval(() => {
        this.save().catch(console.error);
      }, this.config.autoSaveInterval);
    }
  }

  private stopAutoSave(): void {
    if (this.autoSaveTimer) {
      clearInterval(this.autoSaveTimer);
      this.autoSaveTimer = null;
    }
  }
}

// ============================================================================
// Factory
// ============================================================================

let defaultManager: PlanStateManager | null = null;

export function getStateManager(config?: Partial<StateManagerConfig>): PlanStateManager {
  if (!defaultManager) {
    const home = process.env.HOME || process.env.USERPROFILE || "/tmp";
    defaultManager = new PlanStateManager({
      stateDir: path.join(home, ".openclaw", "agent-state"),
      ...config,
    });
  }
  return defaultManager;
}

export function resetStateManager(): void {
  defaultManager = null;
}

/**
 * Automatic Step Completion Detection
 * 
 * Analyzes tool results to determine if plan steps are complete.
 * Uses heuristics and optional LLM verification.
 */

import type { PlanStep, ToolCall, ToolResult, LLMCaller } from "../types.js";
import type { PlanStateManager, PlanState } from "./persistence.js";

// ============================================================================
// Types
// ============================================================================

export interface StepTrackerConfig {
  /** Use LLM to verify completion (more accurate but costs tokens) */
  useLLMVerification: boolean;
  /** Confidence threshold for heuristic-only detection (0-1) */
  heuristicThreshold: number;
  /** Auto-advance to next step on completion */
  autoAdvance: boolean;
  /** Keywords that indicate failure */
  failureKeywords: string[];
  /** Keywords that indicate success */
  successKeywords: string[];
}

export interface CompletionAnalysis {
  isComplete: boolean;
  confidence: number;
  reason: string;
  suggestedResult?: string;
}

const DEFAULT_CONFIG: StepTrackerConfig = {
  useLLMVerification: false,
  heuristicThreshold: 0.7,
  autoAdvance: true,
  failureKeywords: [
    "error", "failed", "failure", "exception", "cannot", "unable",
    "denied", "permission", "not found", "timeout", "refused"
  ],
  successKeywords: [
    "success", "complete", "created", "done", "finished", "wrote",
    "saved", "built", "deployed", "installed", "configured"
  ],
};

// ============================================================================
// Step Tracker
// ============================================================================

export class StepTracker {
  private config: StepTrackerConfig;
  private stateManager: PlanStateManager;
  private llmCaller?: LLMCaller;

  constructor(
    stateManager: PlanStateManager,
    config: Partial<StepTrackerConfig> = {},
    llmCaller?: LLMCaller
  ) {
    this.stateManager = stateManager;
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.llmCaller = llmCaller;
  }

  /**
   * Analyze a tool result to determine if current step is complete
   */
  async analyzeToolResult(
    tool: ToolCall,
    result: ToolResult
  ): Promise<CompletionAnalysis> {
    const state = this.stateManager.getOrNull();
    const activeStep = state ? this.stateManager.getActiveStep() : null;

    if (!activeStep) {
      return {
        isComplete: false,
        confidence: 1.0,
        reason: "No active step to track",
      };
    }

    // First, do heuristic analysis
    const heuristic = this.heuristicAnalysis(activeStep, tool, result);

    // If confident enough or LLM verification disabled, return heuristic
    if (heuristic.confidence >= this.config.heuristicThreshold || !this.config.useLLMVerification) {
      if (heuristic.isComplete && this.config.autoAdvance) {
        this.stateManager.completeStep(activeStep.id, heuristic.suggestedResult);
      }
      return heuristic;
    }

    // Use LLM for verification if available
    if (this.llmCaller) {
      const llmAnalysis = await this.llmVerification(activeStep, tool, result, heuristic);
      if (llmAnalysis.isComplete && this.config.autoAdvance) {
        this.stateManager.completeStep(activeStep.id, llmAnalysis.suggestedResult);
      }
      return llmAnalysis;
    }

    return heuristic;
  }

  /**
   * Manually mark step complete (for explicit completion)
   */
  markComplete(stepId?: string, result?: string): void {
    const state = this.stateManager.getOrNull();
    if (!state?.plan) return;

    const id = stepId ?? state.activeStepId;
    if (id) {
      this.stateManager.completeStep(id, result);
    }
  }

  /**
   * Manually mark step failed
   */
  markFailed(stepId?: string, error?: string): void {
    const state = this.stateManager.getOrNull();
    if (!state?.plan) return;

    const id = stepId ?? state.activeStepId;
    if (id) {
      this.stateManager.failStep(id, error ?? "Step failed");
    }
  }

  /**
   * Check if plan is complete
   */
  isPlanComplete(): boolean {
    const state = this.stateManager.getOrNull();
    if (!state?.plan) return false;

    return state.plan.steps.every(
      s => s.status === "complete" || s.status === "skipped"
    );
  }

  /**
   * Get completion status summary
   */
  getStatus(): {
    hasActivePlan: boolean;
    activeStep: PlanStep | null;
    progress: { completed: number; total: number; percent: number };
    isComplete: boolean;
  } {
    const state = this.stateManager.getOrNull();

    return {
      hasActivePlan: !!state?.plan,
      activeStep: this.stateManager.getActiveStep(),
      progress: this.stateManager.getProgress(),
      isComplete: this.isPlanComplete(),
    };
  }

  // ──────────────────────────────────────────────────────────────────────────
  // Private Methods
  // ──────────────────────────────────────────────────────────────────────────

  private heuristicAnalysis(
    step: PlanStep,
    tool: ToolCall,
    result: ToolResult
  ): CompletionAnalysis {
    const resultText = this.resultToText(result);
    const lowerResult = resultText.toLowerCase();
    const lowerAction = step.action.toLowerCase();
    const lowerCriteria = step.successCriteria.toLowerCase();

    // Check for explicit failure
    const hasFailure = this.config.failureKeywords.some(kw => 
      lowerResult.includes(kw) && !lowerResult.includes(`no ${kw}`)
    );

    if (hasFailure && result.error) {
      return {
        isComplete: false,
        confidence: 0.9,
        reason: `Tool returned error: ${result.error.slice(0, 100)}`,
      };
    }

    // Check for explicit success keywords
    const successCount = this.config.successKeywords.filter(kw =>
      lowerResult.includes(kw)
    ).length;

    // Check if tool matches expected action
    const toolMatchesAction = this.toolMatchesStepAction(tool.name, lowerAction);

    // Check if result mentions success criteria keywords
    const criteriaWords = lowerCriteria.split(/\s+/).filter(w => w.length > 3);
    const criteriaMatches = criteriaWords.filter(w => lowerResult.includes(w)).length;
    const criteriaMatchRatio = criteriaWords.length > 0 
      ? criteriaMatches / criteriaWords.length 
      : 0;

    // Calculate confidence
    let confidence = 0;
    let reasons: string[] = [];

    if (result.success) {
      confidence += 0.4;
      reasons.push("Tool succeeded");
    }

    if (successCount > 0) {
      confidence += Math.min(0.2, successCount * 0.1);
      reasons.push(`Found ${successCount} success indicators`);
    }

    if (toolMatchesAction) {
      confidence += 0.2;
      reasons.push("Tool matches expected action");
    }

    if (criteriaMatchRatio > 0.3) {
      confidence += 0.2 * criteriaMatchRatio;
      reasons.push(`Success criteria ${Math.round(criteriaMatchRatio * 100)}% matched`);
    }

    const isComplete = confidence >= this.config.heuristicThreshold && result.success;

    return {
      isComplete,
      confidence,
      reason: reasons.join("; ") || "Insufficient indicators",
      suggestedResult: isComplete ? this.summarizeResult(resultText) : undefined,
    };
  }

  private async llmVerification(
    step: PlanStep,
    tool: ToolCall,
    result: ToolResult,
    heuristic: CompletionAnalysis
  ): Promise<CompletionAnalysis> {
    if (!this.llmCaller) return heuristic;

    const prompt = `Analyze if this plan step is complete based on the tool result.

Step: ${step.title}
Action: ${step.action}
Success Criteria: ${step.successCriteria}

Tool Used: ${tool.name}
Tool Arguments: ${JSON.stringify(tool.arguments)}
Tool Result: ${this.resultToText(result).slice(0, 1000)}

Heuristic Analysis: ${heuristic.reason} (confidence: ${heuristic.confidence})

Answer in JSON:
{
  "isComplete": true/false,
  "confidence": 0.0-1.0,
  "reason": "Brief explanation",
  "suggestedResult": "One-line summary if complete"
}`;

    try {
      const response = await this.llmCaller({
        messages: [
          { role: "system", content: "You analyze task completion. Output valid JSON only." },
          { role: "user", content: prompt },
        ],
        maxTokens: 200,
      });

      const parsed = JSON.parse(response.content);
      return {
        isComplete: parsed.isComplete ?? heuristic.isComplete,
        confidence: parsed.confidence ?? heuristic.confidence,
        reason: parsed.reason ?? heuristic.reason,
        suggestedResult: parsed.suggestedResult,
      };
    } catch {
      return heuristic;
    }
  }

  private toolMatchesStepAction(toolName: string, action: string): boolean {
    const toolActionMap: Record<string, string[]> = {
      exec: ["run", "execute", "install", "build", "deploy", "create", "setup", "configure"],
      Write: ["write", "create", "save", "add", "generate"],
      Edit: ["edit", "modify", "update", "change", "fix"],
      Read: ["read", "check", "verify", "inspect", "look"],
      web_search: ["search", "find", "research", "look up"],
      web_fetch: ["fetch", "get", "download", "retrieve"],
      browser: ["browse", "navigate", "open", "click", "interact"],
      message: ["send", "message", "notify", "email", "communicate"],
    };

    const keywords = toolActionMap[toolName] ?? [];
    return keywords.some(kw => action.includes(kw));
  }

  private resultToText(result: ToolResult): string {
    if (result.error) return `Error: ${result.error}`;
    if (typeof result.output === "string") return result.output;
    if (result.output) return JSON.stringify(result.output);
    return result.success ? "Success (no output)" : "Failed (no details)";
  }

  private summarizeResult(text: string): string {
    // Take first meaningful line or truncate
    const lines = text.split("\n").filter(l => l.trim().length > 0);
    const firstLine = lines[0] ?? "Completed";
    return firstLine.length > 100 ? firstLine.slice(0, 97) + "..." : firstLine;
  }
}

// ============================================================================
// Factory
// ============================================================================

export function createStepTracker(
  stateManager: PlanStateManager,
  config?: Partial<StepTrackerConfig>,
  llmCaller?: LLMCaller
): StepTracker {
  return new StepTracker(stateManager, config, llmCaller);
}

/**
 * Agent State Machine
 * 
 * Provides observable state transitions for debugging, logging, and dashboards.
 */

import type {
  AgentState,
  StateContext,
  StateObserver,
  StateTransition,
  StateMachineConfig,
} from "../types.js";

// Valid state transitions
const TRANSITIONS: Record<AgentState, AgentState[]> = {
  idle: ["planning"],
  planning: ["executing", "error"],
  executing: ["reflecting", "waiting_human", "recovering", "completing"],
  reflecting: ["executing", "replanning", "completing"],
  replanning: ["executing", "error"],
  waiting_human: ["executing", "planning", "completing", "idle"],
  recovering: ["executing", "replanning", "error"],
  completing: ["idle"],
  error: ["idle"],
  complete: ["idle"],
};

export class AgentStateMachine {
  private context: StateContext;
  private observers: StateObserver[] = [];
  private config: StateMachineConfig;
  private metrics: Map<AgentState, { count: number; totalMs: number }>;

  constructor(config: StateMachineConfig) {
    this.config = config;
    this.context = {
      state: "idle",
      previousState: null,
      enteredAt: Date.now(),
      metadata: {},
      history: [],
    };
    this.metrics = new Map();

    // Initialize metrics for all states
    for (const state of Object.keys(TRANSITIONS) as AgentState[]) {
      this.metrics.set(state, { count: 0, totalMs: 0 });
    }
  }

  /**
   * Transition to a new state
   */
  transition(
    to: AgentState,
    trigger: string,
    metadata?: Record<string, unknown>
  ): void {
    const from = this.context.state;

    // Validate transition
    if (!TRANSITIONS[from].includes(to)) {
      throw new Error(`Invalid transition: ${from} -> ${to}`);
    }

    const now = Date.now();
    const timeInState = now - this.context.enteredAt;

    // Update metrics
    if (this.config.metrics) {
      const stateMetrics = this.metrics.get(from);
      if (stateMetrics) {
        stateMetrics.count += 1;
        stateMetrics.totalMs += timeInState;
      }
    }

    // Record transition
    const transition: StateTransition = {
      from,
      to,
      trigger,
      timestamp: now,
      metadata,
    };

    this.context.history.push(transition);
    this.context.previousState = from;
    this.context.state = to;
    this.context.enteredAt = now;
    this.context.metadata = metadata ?? {};

    // Log transition
    if (this.config.logging) {
      console.log(
        `[FSM] ${from} -> ${to} (${trigger}) [${timeInState}ms in ${from}]`
      );
      if (metadata) {
        console.log(`[FSM] metadata:`, JSON.stringify(metadata));
      }
    }

    // Notify observers
    for (const observer of this.observers) {
      try {
        observer.onTransition(transition);
      } catch (err) {
        console.error("[FSM] Observer error:", err);
      }
    }
  }

  /**
   * Get current state
   */
  getState(): AgentState {
    return this.context.state;
  }

  /**
   * Get full state context
   */
  getContext(): Readonly<StateContext> {
    return { ...this.context, history: [...this.context.history] };
  }

  /**
   * Get transition history
   */
  getHistory(): readonly StateTransition[] {
    return this.context.history;
  }

  /**
   * Get metrics for all states
   */
  getMetrics(): Map<AgentState, { count: number; totalMs: number; avgMs: number }> {
    const result = new Map<AgentState, { count: number; totalMs: number; avgMs: number }>();

    for (const [state, metrics] of this.metrics) {
      result.set(state, {
        count: metrics.count,
        totalMs: metrics.totalMs,
        avgMs: metrics.count > 0 ? metrics.totalMs / metrics.count : 0,
      });
    }

    return result;
  }

  /**
   * Check if a transition is valid
   */
  canTransition(to: AgentState): boolean {
    return TRANSITIONS[this.context.state].includes(to);
  }

  /**
   * Subscribe to state changes
   */
  subscribe(observer: StateObserver): () => void {
    this.observers.push(observer);
    return () => {
      this.observers = this.observers.filter((o) => o !== observer);
    };
  }

  /**
   * Reset the state machine
   */
  reset(): void {
    this.context = {
      state: "idle",
      previousState: null,
      enteredAt: Date.now(),
      metadata: {},
      history: [],
    };

    for (const metrics of this.metrics.values()) {
      metrics.count = 0;
      metrics.totalMs = 0;
    }
  }

  /**
   * Serialize state for persistence
   */
  serialize(): string {
    return JSON.stringify({
      state: this.context.state,
      enteredAt: this.context.enteredAt,
      metadata: this.context.metadata,
      history: this.context.history,
    });
  }

  /**
   * Restore state from persistence
   */
  restore(serialized: string): void {
    try {
      const data = JSON.parse(serialized);
      this.context = {
        state: data.state ?? "idle",
        previousState: null,
        enteredAt: data.enteredAt ?? Date.now(),
        metadata: data.metadata ?? {},
        history: data.history ?? [],
      };
    } catch (err) {
      console.error("[FSM] Failed to restore state:", err);
      this.reset();
    }
  }
}

// ============================================================================
// Built-in Observers
// ============================================================================

/**
 * Logging observer - logs all transitions to console
 */
export class LoggingObserver implements StateObserver {
  private lastTimestamp: number = Date.now();

  onTransition(transition: StateTransition): void {
    const duration = transition.timestamp - this.lastTimestamp;
    console.log(
      `[${new Date(transition.timestamp).toISOString()}] ` +
        `${transition.from} -> ${transition.to} ` +
        `(${transition.trigger}) ` +
        `[${duration}ms]`
    );
    this.lastTimestamp = transition.timestamp;
  }
}

/**
 * Metrics observer - collects timing statistics
 */
export class MetricsObserver implements StateObserver {
  private stateTimers = new Map<AgentState, number>();
  private transitionCounts = new Map<string, number>();
  private stateDurations = new Map<AgentState, number[]>();

  onTransition(transition: StateTransition): void {
    // Track time in previous state
    const entryTime = this.stateTimers.get(transition.from);
    if (entryTime) {
      const duration = transition.timestamp - entryTime;
      const durations = this.stateDurations.get(transition.from) ?? [];
      durations.push(duration);
      this.stateDurations.set(transition.from, durations);
    }

    // Track entry time for new state
    this.stateTimers.set(transition.to, transition.timestamp);

    // Count transitions
    const key = `${transition.from}->${transition.to}`;
    this.transitionCounts.set(key, (this.transitionCounts.get(key) ?? 0) + 1);
  }

  getStats(): {
    transitionCounts: Record<string, number>;
    avgDurations: Record<AgentState, number>;
    totalTransitions: number;
  } {
    const avgDurations: Record<string, number> = {};
    let totalTransitions = 0;

    for (const [state, durations] of this.stateDurations) {
      if (durations.length > 0) {
        avgDurations[state] = durations.reduce((a, b) => a + b, 0) / durations.length;
      }
    }

    for (const count of this.transitionCounts.values()) {
      totalTransitions += count;
    }

    return {
      transitionCounts: Object.fromEntries(this.transitionCounts),
      avgDurations: avgDurations as Record<AgentState, number>,
      totalTransitions,
    };
  }
}

/**
 * Broadcast observer - sends state changes via callback
 */
export class BroadcastObserver implements StateObserver {
  constructor(
    private sessionKey: string,
    private broadcast: (data: unknown) => void
  ) {}

  onTransition(transition: StateTransition): void {
    this.broadcast({
      type: "agent_state_change",
      sessionKey: this.sessionKey,
      data: {
        state: transition.to,
        previousState: transition.from,
        trigger: transition.trigger,
        metadata: transition.metadata,
        timestamp: transition.timestamp,
      },
    });
  }
}

/**
 * Hierarchical Task Management
 * 
 * Provides structured working memory for complex multi-step tasks.
 */

import type { Task, TaskResult, TaskStack, TaskStatus } from "../types.js";

/**
 * Generate a unique task ID
 */
function generateTaskId(): string {
  return `task_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
}

/**
 * Create a new task
 */
export function createTask(
  stack: TaskStack,
  task: Partial<Omit<Task, "id" | "createdAt" | "updatedAt" | "subtasks">>
): Task {
  const newTask: Task = {
    id: generateTaskId(),
    parentId: task.parentId ?? null,
    title: task.title ?? "Untitled",
    description: task.description ?? "",
    status: task.status ?? "pending",
    priority: task.priority ?? 0,
    createdAt: Date.now(),
    updatedAt: Date.now(),
    subtasks: [],
    dependencies: task.dependencies ?? [],
    metadata: task.metadata ?? {},
  };

  if (newTask.parentId) {
    const parent = findTask(stack, newTask.parentId);
    if (parent) {
      parent.subtasks.push(newTask);
      parent.updatedAt = Date.now();
    } else {
      // Parent not found, add as root task
      stack.tasks.push(newTask);
    }
  } else {
    stack.tasks.push(newTask);
  }

  return newTask;
}

/**
 * Find a task by ID (recursive)
 */
export function findTask(stack: TaskStack, taskId: string): Task | null {
  function search(tasks: Task[]): Task | null {
    for (const task of tasks) {
      if (task.id === taskId) return task;
      const found = search(task.subtasks);
      if (found) return found;
    }
    return null;
  }
  return search(stack.tasks);
}

/**
 * Flatten the task tree into a list
 */
export function flattenTasks(stack: TaskStack): Task[] {
  const result: Task[] = [];

  function collect(tasks: Task[]): void {
    for (const task of tasks) {
      result.push(task);
      collect(task.subtasks);
    }
  }

  collect(stack.tasks);
  return result;
}

/**
 * Update task status with result propagation
 */
export function updateTaskStatus(
  stack: TaskStack,
  taskId: string,
  status: TaskStatus,
  result?: TaskResult
): void {
  const task = findTask(stack, taskId);
  if (!task) return;

  task.status = status;
  task.updatedAt = Date.now();
  if (result) task.result = result;

  // If completing, check if parent should also complete
  if (status === "complete" && task.parentId) {
    const parent = findTask(stack, task.parentId);
    if (parent) {
      const allComplete = parent.subtasks.every((t) => t.status === "complete");
      if (allComplete) {
        updateTaskStatus(stack, parent.id, "complete", {
          success: true,
          summary: `All ${parent.subtasks.length} subtasks completed`,
        });
      }
    }
  }

  // If failing, might need to mark parent as blocked
  if (status === "failed" && task.parentId) {
    const parent = findTask(stack, task.parentId);
    if (parent && parent.status === "in_progress") {
      // Check if there are remaining pending subtasks
      const hasPending = parent.subtasks.some((t) => t.status === "pending");
      if (!hasPending) {
        // All subtasks either complete or failed
        const anySuccess = parent.subtasks.some((t) => t.status === "complete");
        updateTaskStatus(stack, parent.id, anySuccess ? "complete" : "failed", {
          success: anySuccess,
          summary: anySuccess
            ? "Some subtasks completed with failures"
            : "All subtasks failed",
        });
      }
    }
  }
}

/**
 * Check if a task has pending dependencies
 */
export function hasPendingDependencies(stack: TaskStack, task: Task): boolean {
  for (const depId of task.dependencies) {
    const dep = findTask(stack, depId);
    if (dep && dep.status !== "complete") {
      return true;
    }
  }
  return false;
}

/**
 * Get the next task to execute (highest priority, no pending deps)
 */
export function getNextTask(stack: TaskStack): Task | null {
  const candidates = flattenTasks(stack)
    .filter((t) => t.status === "pending")
    .filter((t) => !hasPendingDependencies(stack, t))
    .sort((a, b) => b.priority - a.priority);

  return candidates[0] ?? null;
}

/**
 * Get the active task
 */
export function getActiveTask(stack: TaskStack): Task | null {
  if (!stack.activeTaskId) return null;
  return findTask(stack, stack.activeTaskId);
}

/**
 * Set the active task
 */
export function setActiveTask(stack: TaskStack, taskId: string | null): void {
  stack.activeTaskId = taskId;
  if (taskId) {
    const task = findTask(stack, taskId);
    if (task && task.status === "pending") {
      task.status = "in_progress";
      task.updatedAt = Date.now();
    }
  }
}

/**
 * Handle an interruption (steering message)
 */
export function handleInterruption(
  stack: TaskStack,
  message: string,
  urgency: "low" | "medium" | "high" | "critical"
): { action: string; pausedTask?: string; taskId?: string } {
  const activeTask = getActiveTask(stack);

  if (urgency === "critical") {
    // Pause everything, handle immediately
    if (activeTask) {
      activeTask.status = "blocked";
      activeTask.metadata.pausedAt = Date.now();
      activeTask.metadata.pausedBy = "steering";
      activeTask.updatedAt = Date.now();
    }
    return { action: "handle_now", pausedTask: activeTask?.id };
  }

  if (urgency === "high") {
    // Complete current step, then switch
    return { action: "finish_step_then_handle" };
  }

  // Queue for after current task branch
  const interruptTask = createTask(stack, {
    title: "Handle steering message",
    description: message,
    priority: urgency === "medium" ? 5 : 1,
  });

  return { action: "queued", taskId: interruptTask.id };
}

/**
 * Build a context prompt from the task stack
 */
export function buildTaskContextPrompt(stack: TaskStack): string {
  const active = getActiveTask(stack);

  if (!active) return "";

  const allTasks = flattenTasks(stack);
  const completed = allTasks
    .filter((t) => t.status === "complete")
    .map((t) => `- ✓ ${t.title}${t.result?.summary ? ` (${t.result.summary})` : ""}`);

  const pending = allTasks
    .filter((t) => t.status === "pending")
    .map((t) => `- ○ ${t.title}`);

  const inProgress = allTasks
    .filter((t) => t.status === "in_progress" && t.id !== active.id)
    .map((t) => `- ◐ ${t.title}`);

  const lines: string[] = [
    "## Current Task",
    `**${active.title}**`,
  ];

  if (active.description) {
    lines.push(active.description);
  }

  lines.push("");
  lines.push("## Progress");

  if (completed.length > 0) {
    lines.push("### Completed");
    lines.push(...completed);
  }

  if (inProgress.length > 0) {
    lines.push("### In Progress");
    lines.push(...inProgress);
  }

  if (pending.length > 0) {
    lines.push("### Remaining");
    lines.push(...pending);
  }

  return lines.join("\n").trim();
}

/**
 * Create an empty task stack
 */
export function createTaskStack(): TaskStack {
  return {
    tasks: [],
    activeTaskId: null,
  };
}

/**
 * Serialize task stack for persistence
 */
export function serializeTaskStack(stack: TaskStack): string {
  return JSON.stringify(stack, null, 2);
}

/**
 * Restore task stack from persistence
 */
export function restoreTaskStack(serialized: string): TaskStack {
  try {
    return JSON.parse(serialized) as TaskStack;
  } catch {
    return createTaskStack();
  }
}

/**
 * Calculate task completion progress (0-100)
 */
export function calculateProgress(stack: TaskStack): number {
  const allTasks = flattenTasks(stack);
  if (allTasks.length === 0) return 0;

  const completed = allTasks.filter((t) => t.status === "complete").length;
  return Math.round((completed / allTasks.length) * 100);
}

/**
 * Get task statistics
 */
export function getTaskStats(stack: TaskStack): {
  total: number;
  byStatus: Record<TaskStatus, number>;
  maxDepth: number;
  progress: number;
} {
  const allTasks = flattenTasks(stack);
  const byStatus: Record<TaskStatus, number> = {
    pending: 0,
    in_progress: 0,
    blocked: 0,
    complete: 0,
    failed: 0,
    skipped: 0,
  };

  for (const task of allTasks) {
    byStatus[task.status] = (byStatus[task.status] ?? 0) + 1;
  }

  // Calculate max depth
  function depth(task: Task): number {
    if (task.subtasks.length === 0) return 0;
    return 1 + Math.max(...task.subtasks.map(depth));
  }

  const maxDepth = stack.tasks.length > 0
    ? Math.max(...stack.tasks.map(depth))
    : 0;

  return {
    total: allTasks.length,
    byStatus,
    maxDepth,
    progress: calculateProgress(stack),
  };
}

